/* بيانات باب sabr: تُحمَّل عند أول فتح للقسم */
window.SABR = {"ch":[{"id":"anwa","t":"حقيقة الصبر وأنواعه","d":"الآيات التي تبيّن معنى الصبر، وأنواعه الثلاثة: على الطاعة وعن المعصية وعلى الأقدار المؤلمة، وأنه معونة على كل أمر."},{"id":"tawa","t":"الصبر على الطاعة","d":"الآيات التي تأمر بالصبر على العبادة ولزوم الصالحين والأمر بالمعروف والنهي عن المنكر والمرابطة."},{"id":"maasi","t":"الصبر عن المعصية","d":"الآيات التي تربط التقوى بالصبر عن الشهوة والفتنة وإغراء الدنيا وطاعة الآثمين، وعن مقابلة الإساءة بمثلها."},{"id":"bala","t":"الصبر على البلاء","d":"الآيات التي تبيّن سنّة الابتلاء، وما يُقابَل به من الصبر والاسترجاع والثبات والدعاء، في المصيبة والأذى والجهاد."},{"id":"anbiya","t":"صبر الأنبياء والرسل","d":"ما قصّه القرآن من صبر يعقوب وأيوب وإسماعيل وموسى ويونس وخاتم الرسل، وأمره بالاقتداء بأولي العزم."},{"id":"jaza","t":"جزاء الصابرين","d":"الآيات التي تذكر ما وعد الله به الصابرين: الأجر بغير حساب والغرفة والسلام والإمامة والبشرى."}],"tp":[{"id":"isti3ana","ch":"anwa","t":"«واستعينوا بالصبر والصلاة»: الصبر معونة على كل أمر","e":"الأمر بالاستعانة بالصبر والصلاة على الأمور كلها.","ay":[[2,45,46],[2,153,153]],"q":[{"bk":"saadi","s":2,"ay":45,"x":"أمرهم الله أن يستعينوا في أمورهم كلها بالصبر بجميع أنواعه، وهو الصبر على طاعة الله حتى يؤديها، والصبر عن معصية الله حتى يتركها، والصبر على أقدار الله المؤلمة فلا يتسخطها، فبالصبر وحبس النفس على ما أمر الله بالصبر عليه معونة عظيمة على كل أمر من الأمور، ومن يتصبر يصبره الله، وكذلك الصلاة التي هي ميزان الإيمان، وتنهى عن الفحشاء والمنكر يستعان بها على كل أمر من الأمور، {وإنها}؛ أي: الصلاة، {لكبيرة}؛ أي: شاقة {إلا على الخاشعين}؛ فإنها سهلة عليهم خفيفة؛ لأن الخشوع وخشيةَ الله ورجاءَ ما عنده يوجب له فعلها منشرحاً صدره لترقبه للثواب وخشيته من العقاب، بخلاف من لم يكن كذلك، فإنه لا داعي له يدعوه إليها، وإذا فعلها صارت من أثقل الأشياء عليه.","w":"السعدي","en":"Al-Sa'di: Allah commanded them to seek help in all their affairs through patience in all its kinds: patience in obeying Allah until one performs it, patience in refraining from disobeying Him until one leaves it, and patience with His painful decrees without resenting them. Holding oneself to what Allah ordered is a great help in every matter, and whoever makes himself patient, Allah makes him patient. Likewise prayer, the scale of faith, restrains from indecency and wrong and is a help in every matter. It is heavy except for the humble, for whom it is light."},{"bk":"saadi","s":2,"ay":153,"x":"فالصبر هو المعونة العظيمة على كل أمر، فلا سبيل لغير الصابر أن يدرك مطلوبه، خصوصاً الطاعات الشاقة المستمرة فإنها مفتقرة أشد الافتقار إلى تحمل الصبر وتجرع المرارة الشاقة، فإذا لازم صاحبها الصبر فاز بالنجاح، وإن رده المكروه والمشقة عن الصبر والملازمة عليها لم يدرك شيئاً وحصل على الحرمان، وكذلك المعصية التي تشتد دواعي النفس ونوازعها إليها وهي في محل قدرة العبد، فهذه لا يمكن تركها إلا بصبر عظيم وكف لدواعي قلبه ونوازعها لله تعالى واستعانة بالله على العصمة منها فإنها من الفتن الكبار، وكذلك البلاء الشاق خصوصاً إن استمر، فهذا تضعف معه القوى النفسانية والجسدية ويوجد مقتضاها وهو التسخط إن لم يقاومها صاحبها بالصبر لله والتوكل عليه واللجْأ إليه والافتقار على الدوام، فعلمت أن الصبر محتاج إليه العبد …","w":"السعدي","en":"Al-Sa'di: patience is the great help in every matter, and the one who is not patient cannot reach what he seeks, especially lasting hard acts of obedience. Disobedience whose pull is strong and within one's reach can only be left with great patience, holding back the heart's urges and seeking Allah's help to be protected. Likewise a hard trial, especially a lasting one, weakens the strength of soul and body unless met with patience, trust in Allah, turning to Him and need of Him."}]},{"id":"anwa3","ch":"anwa","t":"أنواع الصبر الثلاثة: على الطاعة وعن المعصية وعلى الأقدار","e":"بيان أن الصبر على طاعة الله وعن معصيته وعلى أقداره.","ay":[[103,1,3],[31,31,31]],"q":[{"bk":"saadi","s":103,"ay":3,"x":"والتَّواصي بالصَّبر على طاعة الله، وعن معصية الله، وعلى أقدار الله المؤلمة.","w":"السعدي","en":"Al-Sa'di: counselling one another to patience means patience in Allah's obedience, away from disobeying Him, and upon His painful decrees."},{"bk":"saadi","s":31,"ay":31,"x":"على السَّراء، صبَّارٍ على طاعة الله وعن معصيته وعلى أقدارِهِ، شكورٍ لله على نِعَمِهِ الدينيَّة والدنيويَّة.","w":"السعدي","en":"Al-Sa'di: the patient, grateful one is patient in hardship and grateful in ease; patient in obeying Allah, away from His disobedience and upon His decrees, grateful to Allah for His religious and worldly favours."},{"bk":"qurtubi","s":2,"ay":155,"x":"وَالصَّبْرُ صَبْرَانِ: صَبْرٌ عَنْ مَعْصِيَةِ اللَّهِ، فَهَذَا مُجَاهِدٌ، وَصَبْرٌ عَلَى طَاعَةِ اللَّهِ، فَهَذَا عَابِدٌ. فَإِذَا صَبَرَ عَنْ مَعْصِيَةِ اللَّهِ وَصَبَرَ عَلَى طَاعَةِ اللَّهِ أَوْرَثَهُ اللَّهُ الرِّضَا بِقَضَائِهِ، وَعَلَامَةُ الرِّضَا سُكُونُ الْقَلْبِ بِمَا وَرَدَ عَلَى النَّفْسِ مِنَ الْمَكْرُوهَاتِ وَالْمَحْبُوبَاتِ.","w":"القرطبي","en":"Al-Qurtubi: patience is of two kinds: patience away from disobedience, which is the mujahid, and patience in obedience, which is the worshipper. When one is patient in both, Allah grants him contentment with His decree, and the sign of contentment is the heart's calm toward what befalls the self of the disliked and the liked."}]},{"id":"habs","ch":"anwa","t":"حبس النفس وفطامها: حقيقة الصبر وحدّه","e":"معنى الصبر عند أهل التفسير: حبس النفس وما قيل في حدّه.","ay":[[21,85,86]],"q":[{"bk":"saadi","s":21,"ay":85,"x":"والصبر: هو حَبْسُ النفس ومنعها مما تميل بطبعها إليه، وهذا يشملُ أنواع الصبر الثلاثة: الصبرُ على طاعة الله، والصبرُ عن معصيةِ الله، والصبرُ على أقدار الله المؤلمة. فلا يستحقُّ العبد اسم الصبرِ التامِّ حتى يوفِّي هذه الثلاثة حقَّها؛ فهؤلاء الأنبياء عليهم الصلاة والسلام قد وَصَفَهم الله بالصبرِ؛ فدلَّ أنَّهم وفَّوْها حقَّها وقاموا بها كما ينبغي.","w":"السعدي","en":"Al-Sa'di: patience is holding the self back and preventing it from what it naturally inclines to. It covers the three kinds: patience in obeying Allah, patience away from disobeying Him and patience with His painful decrees. A servant does not deserve the name of complete patience until he gives all three their due. Allah described these prophets as patient, which shows they gave them their due."},{"bk":"qurtubi","s":2,"ay":155,"x":"وَقَالَ الْخَوَّاصُ: الصَّبْرُ الثَّبَاتُ عَلَى أَحْكَامِ الْكِتَابِ وَالسُّنَّةِ. وَقَالَ رُوَيْمٌ: الصَّبْرُ تَرْكُ الشَّكْوَى. وَقَالَ ذُو النُّونِ الْمِصْرِيُّ: الصَّبْرُ هُوَ الِاسْتِعَانَةُ بِاللَّهِ تَعَالَى. وَقَالَ الْأُسْتَاذُ أَبُو عَلِيٍّ: الصَّبْرُ حَدُّهُ أَلَّا تَعْتَرِضَ عَلَى التَّقْدِيرِ، فَأَمَّا إِظْهَارُ الْبَلْوَى عَلَى غَيْرِ وَجْهِ الشَّكْوَى فَلَا يُنَافِي الصَّبْرَ، قَالَ اللَّهُ تَعَالَى فِي قِصَّةِ أَيُّوبَ:\" إِنَّا وَجَدْناهُ صابِراً نِعْمَ الْعَبْدُ \"مَعَ مَا أَخْبَرَ عَنْهُ أنه قال:\" مَسَّنِيَ الضُّرُّ\".","w":"القرطبي","en":"Al-Qurtubi: al-Khawwas said patience is steadfastness upon the rulings of the Book and the Sunnah; Ruwaym said it is leaving complaint; Dhu al-Nun al-Misri said it is seeking Allah's help; Abu Ali said its limit is not objecting to the decree, and showing one's affliction without complaining does not contradict patience, as Allah said of Job: \"We found him patient, an excellent servant,\" although he said: \"Harm has touched me.\""}]},{"id":"jamil","ch":"anwa","t":"«فاصبر صبراً جميلاً»: الصبر الذي لا شكوى فيه إلى الخلق","e":"الصبر الذي لا سخط فيه ولا شكوى إلى الخلق، وشكوى البثّ إلى الله.","ay":[[70,5,5],[12,18,18],[12,83,86]],"q":[{"bk":"saadi","s":70,"ay":5,"x":"وقوله: {فاصۡبِرۡ صبراً جميلاً}؛ أي: اصبر على دعوتك لقومك صبراً جميلاً، لا تَضَجُّرَ فيه ولا ملل، بل استمرَّ على أمر الله، وادعُ عباده إلى توحيده، ولا يمنعْك عنهم ما ترى من عدم انقيادهم وعدم رغبتهم؛ فإنَّ في الصَّبر على ذلك خيراً كثيراً.","w":"السعدي","en":"Al-Sa'di: be patient with your calling of your people, a beautiful patience with no vexation or weariness; continue on Allah's command and call His servants to His oneness, and do not let their lack of response stop you, for there is much good in that patience."},{"bk":"saadi","s":12,"ay":18,"x":"أي: أمَّا أنا؛ فوظيفتي سأحرص على القيام بها، وهي أني أصبر على هذه المحنة صبراً جميلاً سالماً من السخط والتشكي إلى الخلق، وأستعين الله على ذلك لا على حولي وقوتي، فوعد من نفسه هذا الأمر، وشكا إلى خالقه في قوله:{إنَّما أشكو بثِّي وحُزۡني إلى الله}: لأنَّ الشكوى إلى الخالق لا تنافي الصبر الجميل؛ لأنَّ النبيَّ إذا وعد وفى.","w":"السعدي","en":"Al-Sa'di: Jacob said that his task is to bear this trial with a beautiful patience free of resentment and complaint to people, seeking Allah's help and not relying on his own strength. He promised this of himself yet complained to his Creator: \"I only complain of my grief and sorrow to Allah,\" because complaint to the Creator does not contradict beautiful patience, and a prophet fulfils what he promises."},{"bk":"ibnkathir","s":12,"ay":86,"x":"قَالَ لَهُمْ كَمَا قَالَ لَهُمْ حِينَ جَاءُوا عَلَى قَمِيصِ يُوسُفَ بِدَمٍ كَذِبٍ: ﴿بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ﴾ قَالَ مُحَمَّدُ بْنُ إِسْحَاقَ: لَمَّا جَاءُوا يَعْقُوبَ وَأَخْبَرُوهُ بِمَا يَجْرِي اتِّهَمَهُمْ، وَظَنَّ أَنَّهَا كَفَعْلَتِهِمْ بِيُوسُفَ ﴿قَالَ بَلْ سَوَّلَتْ لَكُمْ أَنْفُسُكُمْ أَمْرًا فَصَبْرٌ جَمِيلٌ﴾ .","w":"ابن كثير","en":"Ibn Kathir: he said to them what he said when they came with Joseph's shirt stained with false blood: \"Rather, your souls have enticed you to something, so patience is beautiful.\" Ibn Ishaq said that when they came and told Jacob what had happened, he suspected them and thought it was like what they did to Joseph."}]},{"id":"tawasi","ch":"anwa","t":"التواصي بالصبر: وصية الأمة بعضها لبعض","e":"وصف الذين آمنوا بالتواصي بالصبر والتواصي بالمرحمة.","ay":[[103,1,3],[90,17,17]],"q":[{"bk":"saadi","s":90,"ay":17,"x":"{ثم كان من الذين آمنوا}: وعملوا الصالحات ؛ أي: آمنوا بقلوبهم بما يجب الإيمان به، وعملوا الصالحات بجوارحهم، فدخل في هذا كلُّ قول وفعل واجبٍ أو مستحبٍّ، {وتواصَوۡا بالصَّبۡرِ}: على طاعة الله وعن معصيته وعلى أقداره المؤلمة؛ بأن يحثَّ بعضهم بعضاً على الانقياد لذلك والإتيان به كاملاً منشرحاً به الصَّدر مطمئنَّةً به النفس، {وتواصَوۡا بالمَرۡحَمَةِ}: للخلق؛ من إعطاء محتاجهم، وتعليم جاهلهم، والقيام بما يحتاجون إليه من جميع الوجوه، ومساعدتهم على المصالح الدينيَّة والدنيويَّة، وأن يحبَّ لهم ما يحبُّ لنفسه، ويكره لهم ما يكره لنفسه.","w":"السعدي","en":"Al-Sa'di: \"then he was of those who believed\" means they believed with their hearts and did righteous deeds with their limbs, every obligatory or recommended word and deed; \"and counselled one another to patience\" upon Allah's obedience, away from disobeying Him and upon His painful decrees, urging one another to submit fully with an open chest; \"and counselled one another to compassion\" for people: giving to the needy, teaching the ignorant, serving their needs, and loving for them what one loves for oneself."}]},{"id":"salat","ch":"tawa","t":"«وأمر أهلك بالصلاة واصطبر عليها»","e":"الأمر بالصبر على الصلاة والثبات عليها.","ay":[[20,132,132],[19,65,65]],"q":[{"bk":"saadi","s":20,"ay":132,"x":"أي: على الصلاة بإقامتها بحدودها وأركانها [وآدابها] وخشوعها؛ فإنَّ ذلك مشقٌّ على النفس، ولكنْ ينبغي إكراهها وجهادُها على ذلك والصبر معها دائماً؛ فإنَّ العبد إذا أقام صلاته على الوجه المأمور به؛ كان لما سِواها من دينِهِ أحفظَ وأقوم، وإذا ضيَّعها؛ كان لما سِواها أضيعَ.","w":"السعدي","en":"Al-Sa'di: be patient upon prayer by performing it with its limits, pillars, etiquette and humility. That is hard on the self, but one should force oneself and strive and be patient with it always, for if a servant establishes his prayer as commanded, the rest of his religion is better guarded, and if he neglects it, the rest is more neglected."}]},{"id":"suhba","ch":"tawa","t":"«واصبر نفسك مع الذين يدعون ربهم»: الصبر على صحبة الصالحين","e":"الأمر بحبس النفس مع الذاكرين وعدم طاعة من أغفل الله قلبه.","ay":[[18,28,28]],"q":[{"bk":"saadi","s":18,"ay":28,"x":"والصبر المذكور في هذه الآية هو الصبر على طاعة الله، الذي هو أعلى أنواع الصبر، وبتمامه يتمُّ باقي الأقسام.","w":"السعدي","en":"Al-Sa'di: the patience mentioned in this verse is patience in obeying Allah, the highest kind of patience, and with its completion the other kinds are completed."}]},{"id":"ihsan","ch":"tawa","t":"«واصبر فإن الله لا يضيع أجر المحسنين»","e":"الأمر بالصبر وبيان أنه لا يضيع به أجر المحسنين.","ay":[[11,115,115]],"q":[{"bk":"saadi","s":11,"ay":115,"x":"ولكن تلك الأمور تحتاج إلى مجاهدة النفس والصبر عليها، ولهذا قال:{واصبِرۡ}؛ أي: احبس نفسك على طاعة اللَّه وعن معصيته وإلزامها لذلك واستمرَّ ولا تضجر.","w":"السعدي","en":"Al-Sa'di: those matters need striving against the self and patience in them, so He said \"and be patient\": hold yourself to obeying Allah and away from disobeying Him, keep to it and do not grow weary."},{"bk":"saadi","s":11,"ay":115,"x":"وفي هذا ترغيبٌ عظيمٌ للزوم الصبر بتشويق النفس الضعيفة إلى ثواب الله كلَّما وَنَتْ وَفَتَرَتْ.","w":"السعدي","en":"Al-Sa'di: in this is a great encouragement to keep to patience, by drawing the weak self toward Allah's reward whenever it slackens and tires."}]},{"id":"luqman","ch":"tawa","t":"وصية لقمان: الأمر والنهي يحتاج إلى صبر","e":"وصية لقمان لابنه بالصبر على ما يصيب في الأمر والنهي.","ay":[[31,17,17]],"q":[{"bk":"saadi","s":31,"ay":17,"x":"ولمَّا عُلِمَ أنَّه لا بدَّ أن يُبتلى إذا أمر ونهى وأنَّ في الأمر والنهي مشقَّة على النفوس؛ أمره بالصبر على ذلك، فقال:{واصبِرۡ على ما أصابَكَ إنَّ ذلك}: الذي وَعَظَ به لقمانُ ابنَه {من عزم الأمورِ}؛ أي: من الأمور التي يُعْزَمُ عليها، ويهتمُّ بها، ولا يوفَّق لها إلا أهلُ العزائم.","w":"السعدي","en":"Al-Sa'di: since he knew that whoever enjoins and forbids must be tested, and that enjoining and forbidding is hard on souls, he commanded him to be patient with that: \"and be patient over what befalls you; that is of the matters of resolve,\" that is, of the matters one resolves upon and cares about, which only people of resolve are granted."}]},{"id":"ribat","ch":"tawa","t":"«اصبروا وصابروا ورابطوا»","e":"الأمر بالصبر والمصابرة والمرابطة وربطها بالفلاح.","ay":[[3,200,200]],"q":[{"bk":"saadi","s":3,"ay":200,"x":"والمصابرة: هي الملازمة والاستمرار على ذلك على الدوام، ومقاومة الأعداء في جميع الأحوال.","w":"السعدي","en":"Al-Sa'di: mutual endurance means keeping to it continually and facing the enemies in all circumstances."},{"bk":"saadi","s":3,"ay":200,"x":"فعلم من هذا أنه لا سبيل إلى الفلاح بدون الصبر والمصابرة والمرابطة المذكورات، فلم يفلح مَنْ أفلح إلا بها ولم يفت أحداً الفلاحُ إلا بالإخلال بها أو ببعضها.","w":"السعدي","en":"Al-Sa'di: from this we learn that there is no way to success without the patience, endurance and standing firm mentioned; no one succeeded except through them, and none missed success except by neglecting them or some of them."},{"bk":"qurtubi","s":3,"ay":200,"x":"وَقَالَ عَطَاءٌ وَالْقُرَظِيُّ: صَابِرُوا الْوَعْدَ الَّذِي وُعِدْتُمْ أَيْ لَا تَيْأَسُوا وَانْتَظِرُوا الْفَرَجَ، قَالَ ﷺ: (انْتِظَارُ الْفَرَجِ بِالصَّبْرِ عِبَادَةٌ).","w":"القرطبي","en":"Al-Qurtubi: Ata and al-Qurazi said: 'outlast the promise you were given', meaning do not despair and wait for relief. The Prophet, peace be upon him, said: (Waiting for relief with patience is worship)."}]},{"id":"layl","ch":"tawa","t":"الصبر على ما يقولون وقيام الليل وذكر الله","e":"الأمر بالصبر على أذى المعاندين مع الذكر والعبادة والهجر الجميل.","ay":[[73,1,10]],"q":[{"bk":"saadi","s":73,"ay":10,"x":"فلما أمره الله بالصَّلاة خصوصاً وبالذِّكر عموماً، وذلك يحصل للعبد مَلَكَةٌ قويةٌ في تحمُّل الأثقال وفعل المُشِقِّ من الأعمال؛ أمره بالصبر على ما يقوله المعاندون له ويسبُّونه ويسبُّون ما جاء به، وأن يمضِيَ على أمر الله؛ لا يصدُّه عنه صادٌّ ولا يردُّه رادٌّ، وأن يَهْجُرَهُم هجراً جميلاً، وهو الهجر حيث اقتضت المصلحةُ [الهجرَ]، الذي لا أذيَّة فيه، بل يعاملهم بالهجر والإعراض عن أقوالهم التي تؤذيه، وأمره بجدالهم بالتي هي أحسن.","w":"السعدي","en":"Al-Sa'di: when Allah commanded him to pray in particular and to remember Him in general, which gives a servant a strong faculty for bearing burdens and hard work, He commanded him to be patient over what the stubborn say, insulting him and what he brought, to continue on Allah's command with nothing blocking him, and to withdraw from them gracefully where that serves, without harm, turning away from the words that hurt him, and to argue with them in the best way."}]},{"id":"yusuf33","ch":"maasi","t":"يوسف عليه السلام: «رب السجن أحب إلي مما يدعونني إليه»","e":"امتناع يوسف عليه السلام عن الفاحشة وتفضيله السجن عليها.","ay":[[12,23,24],[12,33,33]],"q":[{"bk":"saadi","s":12,"ay":33,"x":"فعند ذلك اعتصم يوسف بربِّه، واستعان به على كيدهِنَّ و {قال ربِّ السجنُ أحبُّ إليَّ مما يدعونني إليه}: وهذا يدلُّ على أن النسوة جعلن يُشِرْن على يوسف في مطاوعة سيدته، وجعلن يَكِدْنَه في ذلك، فاستحبَّ السجن والعذاب الدنيويَّ على لذَّة حاضرة توجب العذاب الشديد.","w":"السعدي","en":"Al-Sa'di: at that point Joseph took refuge in his Lord and sought His help against their scheming and said: \"My Lord, prison is dearer to me than what they invite me to.\" This shows the women kept urging Joseph to yield to his mistress and plotting against him, so he preferred prison and worldly punishment to a present pleasure that brings severe punishment."},{"bk":"saadi","s":12,"ay":23,"x":"والحاصل أنَّه جعل الموانع له من هذا الفعل: تَقْوى الله، ومراعاة حقِّ سيِّده الذي أكرمه، وصيانة نفسه عن الظُّلم الذي لا يفلح مَن تعاطاه، وكذلك ما منَّ الله عليه من برهان الإيمان الذي في قلبه يقتضي منه امتثالَ الأوامر واجتنابَ الزواجر، والجامعُ لذلك كلِّه أنَّ الله صرف عنه السوءَ والفحشاءَ؛ لأنَّه من عباده المخلصين له في عباداتهم، الذين أخلصهم الله واختارهم واختصَّهم لنفسه، وأسدى عليهم من النِّعم، وصرف عنهم من المكاره ما كانوا به من خيار خلقه.","w":"السعدي","en":"Al-Sa'di: in sum, what prevented him from the act was fear of Allah, regard for his master's right who honoured him, and guarding himself from wrong that does not succeed; and the proof of faith in his heart that calls for obeying commands and avoiding prohibitions. All of it is summed up in that Allah turned evil and indecency away from him, because he was among His sincere servants whom He chose for Himself, favoured and shielded from what is disliked."}]},{"id":"yusuf90","ch":"maasi","t":"«إنه من يتق ويصبر»: التقوى والصبر","e":"قول يوسف لإخوته: من يتق ويصبر فإن الله لا يضيع أجر المحسنين.","ay":[[12,90,90]],"q":[{"bk":"saadi","s":12,"ay":90,"x":"فعرفوا أن الذي خاطبهم هو يوسفُ، فقالوا:{أإنَّك لأنت يوسفُ قال أنا يوسفُ وهذا أخي قد منَّ الله علينا}: بالإيمان والتقوى والتمكين في الدُّنيا، وذلك بسبب الصبر والتقوى، فَـ {إنَّه من يتَّقِ ويَصۡبِرۡ}؛ أي: يتَّقي فعل ما حرَّم الله ويصبر على الآلام والمصائب وعلى الأوامر بامتثالها.","w":"السعدي","en":"Al-Sa'di: they realised the one speaking to them was Joseph and said: \"Are you indeed Joseph?\" He said: \"I am Joseph and this is my brother; Allah has favoured us\" with faith, piety and power in the land, and that was because of patience and piety, for \"whoever fears Allah and is patient\": fears doing what Allah forbade and is patient upon pains and calamities and in carrying out commands."}]},{"id":"ahsan","ch":"maasi","t":"«ادفع بالتي هي أحسن»: ولا يلقاها إلا الذين صبروا","e":"أن مقابلة الإساءة بالإحسان لا يوفَّق لها إلا الصابرون.","ay":[[41,34,35]],"q":[{"bk":"saadi","s":41,"ay":35,"x":"{وما يُلَقَّاها}؛ أي: وما يوفَّق لهذه الخصلة الحميدة {إلاَّ الذين} صَبَّرُوا نفوسَهم على ما تكره، وأجبروها على ما يحبُّه الله؛ فإنَّ النفوس مجبولةٌ على مقابلة المسيء بإساءتِهِ، وعدم العفو عنه؛ فكيف بالإحسان؛ فإذا صبَّر الإنسان نفسَه وامتثل أمر ربِّه وعرف جزيلَ الثواب وعلمَ أنَّ مقابلته للمسيء بجنس عمله لا يفيده شيئاً ولا يزيدُ العداوة إلاَّ شدة، وأنَّ إحسانه إليه ليس بواضع قدرَه، بل مَنْ تواضَعَ لله رَفَعَه؛ هان عليه الأمرُ وفعل ذلك متلذِّذاً مستحلياً له.","w":"السعدي","en":"Al-Sa'di: \"none is granted it\" means none is given success in this noble trait \"except those who\" held their souls patient against what they dislike and forced them to what Allah loves. Souls are made to answer the wrongdoer with his wrong and not to forgive, let alone do good; but when a person holds himself patient, obeys his Lord, knows the great reward and knows that answering in kind gains nothing and only increases enmity, while his kindness lowers him not but whoever humbles himself to Allah is raised, it becomes easy and he does it with enjoyment."}]},{"id":"qarun","ch":"maasi","t":"«ولا يلقاها إلا الصابرون»: الصبر عن فتنة الدنيا","e":"قول العلماء عند فتنة قارون: لا يلقّاها إلا الصابرون.","ay":[[28,79,80]],"q":[{"bk":"saadi","s":28,"ay":80,"x":"{وقال الذين أوتوا العلم}: الذين عرفوا حقائقَ الأشياء ونظروا إلى باطن الدنيا حين نظر أولئك إلى ظاهرها: {ويلَكُم}: متوجِّعين من ما تمنَّوا لأنفسهم، راثين لحالهم، منكرين لمقالهم، {ثوابُ الله}: العاجلُ من لذَّة العبادة ومحبَّته والإنابة إليه والإقبال عليه، والآجلُ من الجنَّة وما فيها ممَّا تشتهيه الأنفس وتلذُّ الأعينُ خير من هذا الذي تمنَّيْتُم ورغبتُم فيه؛ فهذه حقيقة الأمر، ولكنْ ما كلُّ مَنْ يعلم ذلك يؤثر الأعلى على الأدنى، فما يُلَقَّى ذلك ويوفَّقُ له {إلاَّ الصابِرونَ}: الذين حبسوا أنفسَهم على طاعة الله وعن معصيتِهِ وعلى أقدارِهِ المؤلمةِ وصبروا على جواذب الدُّنيا وشهواتِها أن تَشْغَلَهم عن ربِّهم وأن تحولَ بينهم وبينَ ما خُلِقوا له؛ فهؤلاء الذين يؤثرون ثوابَ الله على الدُّنيا الفانية.","w":"السعدي","en":"Al-Sa'di: those given knowledge, who knew the realities of things and looked at the inside of the world while the others looked at its surface, said \"Woe to you!\", grieving at what they wished for themselves: Allah's reward, both the immediate, the joy of worship, love of Him and turning to Him, and the later, Paradise, is better than what you wished for. Not everyone who knows this prefers the higher to the lower; this is granted only to the patient, who held themselves to Allah's obedience, away from His disobedience and upon His painful decrees, and endured the pulls of the world so they would not distract them from their Lord or what they were created for."}]},{"id":"lataTi3","ch":"maasi","t":"«فاصبر لحكم ربك ولا تطع منهم آثماً أو كفوراً»","e":"الأمر بالصبر لحكم الله وعدم طاعة الآثم والكفور.","ay":[[76,24,26]],"q":[{"bk":"saadi","s":76,"ay":24,"x":"ولهذا قال: {فاصبر لحكم ربِّكَ ولا تُطِعۡ منهم آثماً أو كفوراً}؛ أي: اصبر لحكمه القدريِّ؛ فلا تسخطه، ولحكمه الدينيِّ؛ فامض عليه، ولا يعوقَنَّك عنه عائقٌ، {ولا تطعۡ}: من المعاندين الذين يريدونَ أن يَصُدُّوك {آثماً}؛ أي: فاعلاً إثماً ومعصيةً، {ولا كفوراً}: فإنَّ طاعة الكفَّار والفجَّار والفسَّاق لا بدَّ أن تكون معصيةً لله ؛ فإنَّهم لا يأمرون إلاَّ بما تهواه أنفسهم.","w":"السعدي","en":"Al-Sa'di: \"be patient with your Lord's decree\": with His decree of fate do not resent it, and with His religious decree carry on with it and let nothing hinder you; \"and do not obey among them a sinner or a disbeliever\", for obeying the disbelievers, the wicked and the transgressors is bound to be disobedience to Allah, since they only command what their desires want."},{"bk":"saadi","s":76,"ay":24,"x":"ولما كان الصبر يُسْتَمَدُّ من القيام بطاعة الله والإكثار من ذِكْرِه؛ أمر الله بذلك، فقال:{واذكُرِ اسمَ ربِّك بكرةً وأصيلاً}؛ أي: أول النهار وآخره، فدخل في ذلك الصلوات المكتوبات، وما يتبعها من النَّوافل والذِّكْر والتَّسبيح والتَّهليل والتَّكبير في هذه الأوقات.","w":"السعدي","en":"Al-Sa'di: since patience is drawn from keeping to Allah's obedience and remembering Him much, Allah commanded that: \"and remember the name of your Lord morning and evening\", the beginning and end of the day, including the obligatory prayers, their voluntary prayers, remembrance, glorifying and magnifying at these times."}]},{"id":"ghayr","ch":"maasi","t":"الصبر عن الغضب والانتقام: «ولمن صبر وغفر»","e":"الصبر على الأذى والمغفرة، وكون العفو خيراً للصابرين.","ay":[[42,40,43],[16,126,127]],"q":[{"bk":"saadi","s":42,"ay":43,"x":"{وَلَمَن صَبَرَ}: على ما ينالُه من أذى الخلق، {وغَفَرَ}: لهم بأن سمح لهم عمَّا يصدر منهم {إنَّ ذلك لَمِنۡ عزم الأمور}؛ أي: لمن الأمور التي حثَّ اللهُ عليها وأكَّدها وأخبر أنَّه لا يُلَقَّاها إلاَّ أهلُ الصبر والحظوظِ العظيمة، ومن الأمور التي لا يوفَّق لها إلاَّ أولو العزائم والهمم وذوو الألباب والبصائر؛ فإنَّ ترك الانتصار للنفس بالقول أو الفعل من أشقِّ شيء عليها، والصبر على الأذى والصفح عنه ومغفرتِهِ ومقابلتِهِ بالإحسان أشقُّ وأشقُّ، ولكنَّه يسيرٌ على من يسَّره الله عليه وجاهد نفسَه على الاتِّصاف به، واستعانَ اللهَ على ذلك، ثم إذا ذاقَ العبدُ حلاوته، ووجد آثارَه؛ تلقَّاه برحب الصدرِ وسعة الخُلُق والتلذُّذ فيه.","w":"السعدي","en":"Al-Sa'di: \"and whoever is patient\" over harm from people \"and forgives\" by overlooking what comes from them, \"that is of the matters of resolve\": among what Allah urged and stressed and said only people of patience and great fortune are granted. Giving up retaliation by word or deed is the hardest thing for the self, and bearing harm, pardoning and repaying with kindness is harder still, yet it is easy for whom Allah makes it easy and who strives to have it, and then when he tastes its sweetness he meets it with a wide chest and enjoyment."},{"bk":"saadi","s":16,"ay":127,"x":"عن المعاقبة وعفوتُم عن جرمهم، {لهو خيرٌ للصَّابرينَ}: من الاستيفاء، وما عند الله خيرٌ لكم وأحسن عاقبةً؛ كما قال تعالى:{فمن عفا وأصۡلَحَ فأجۡرُهُ على الله}.","w":"السعدي","en":"Al-Sa'di: if you are patient, forgoing punishment and pardoning their offence, it is better for the patient than taking full repayment, and what is with Allah is better for you and a better outcome, as He said: \"Whoever pardons and reconciles, his reward is with Allah.\""}]},{"id":"ibtila","ch":"bala","t":"«ولنبلونكم بشيء من الخوف والجوع»","e":"سنّة الابتلاء بالخوف والجوع ونقص الأموال، وبشارة الصابرين.","ay":[[2,155,157]],"q":[{"bk":"saadi","s":2,"ay":155,"x":"أخبر تعالى أنه لا بد أن يبتليَ عباده بالمحن ليتبين الصادق من الكاذب والجازع من الصابر، وهذه سنته تعالى في عباده، لأن السراء لو استمرت لأهل الإيمان ولم يحصل معها محنة لحصل الاختلاط الذي هو فساد، وحكمة الله تقتضي تمييز أهل الخير من أهل الشر، هذه فائدة المحن لا إزالة ما مع المؤمنين من الإيمان ولا ردهم عن دينهم، فما كان الله ليضيع إيمان المؤمنين.","w":"السعدي","en":"Al-Sa'di: Allah told that He will surely test His servants with trials so that the truthful is distinguished from the liar and the impatient from the patient; this is His way with His servants. If ease continued for the believers with no trial, there would be a corrupting mixture, and His wisdom requires distinguishing the good from the bad. The benefit of trials is not to remove the faith the believers have, nor to turn them from their religion, for Allah would never waste their faith."},{"bk":"saadi","s":2,"ay":155,"x":"وأما من وفقه الله للصبر عند وجود هذه المصائب فحبس نفسه عن التسخط قولاً وفعلاً واحتسب أجرها عند الله وعلم أن ما يدركه من الأجر بصبره أعظم من المصيبة التي حصلت له، بل المصيبة تكون نعمة في حقه لأنها صارت طريقاً لحصول ما هو خير له وأنفع منها، فقد امتثل أمر الله وفاز بالثواب، فلهذا قال تعالى:{وبشر الصابرين}؛ أي: بشرهم بأنهم يوفون أجرهم بغير حساب، فالصابرون هم الذين فازوا بالبشارة العظيمة والمنحة الجسيمة، ثم وصفهم بقوله: {156}{الذين إذا أصابتهم مصيبة}؛ وهي كل ما يؤلم القلب أو البدن أو كليهما مما تقدم ذكره، {قالوا إنا لله}؛ أي: مملوكون لله مدبرون تحت أمره وتصريفه فليس لنا من أنفسنا وأموالنا شيء …","w":"السعدي","en":"Al-Sa'di: as for whom Allah grants patience at these calamities, he held himself back from resentment in word and deed, hoped for reward from Allah and knew that the reward for his patience is greater than the calamity, indeed the calamity becomes a favour to him, for it is a path to what is better and more beneficial for him. He obeyed Allah's command and won the reward, so Allah said: \"and give good tidings to the patient\", glad tidings that they will be paid their reward without measure. Then He described them: \"Those who, when a calamity strikes them,\" which is whatever pains the heart or body or both, \"say: Indeed we belong to Allah\", that is, we are owned by Allah and managed under His command and direction, and we have nothing of ourselves or our wealth."},{"bk":"saadi","s":2,"ay":155,"x":"فقد اشتملت هاتان الآيتان على توطين النفوس على المصائب قبل وقوعها لتخف وتسهل إذا وقعت، وبيان ما تقابل به إذا وقعت وهو الصبر، وبيان ما يعين على الصبر وما للصابرين من الأجر.","w":"السعدي","en":"Al-Sa'di: these two verses include preparing souls for calamities before they happen, so they become lighter when they do; stating how to meet them, which is patience; stating what helps patience; and stating the reward of the patient."}]},{"id":"sadma","ch":"bala","t":"الصبر عند الصدمة الأولى","e":"أن الصبر المحمود عند أول المصيبة.","ay":[[2,156,157]],"q":[{"bk":"qurtubi","s":2,"ay":155,"x":"لَكِنْ لَا يَكُونُ ذَلِكَ إِلَّا بِالصَّبْرِ عِنْدَ الصَّدْمَةِ الْأُولَى، كَمَا رَوَى الْبُخَارِيُّ عَنْ أَنَسٍ عَنِ النَّبِيِّ ﷺ قَالَ: (إِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الْأُولَى). وَأَخْرَجَهُ مُسْلِمٌ أَتَمَّ مِنْهُ، أَيْ إِنَّمَا الصَّبْرُ الشَّاقُّ عَلَى النَّفْسِ الَّذِي يَعْظُمُ الثَّوَابُ عَلَيْهِ إِنَّمَا هُوَ عِنْدَ هُجُومِ الْمُصِيبَةِ وَحَرَارَتِهَا، فَإِنَّهُ يَدُلُّ عَلَى قُوَّةِ الْقَلْبِ وَتَثَبُّتِهِ فِي مَقَامِ الصَّبْرِ، وَأَمَّا إِذَا بَرَدَتْ حَرَارَةُ الْمُصِيبَةِ فَكُلُّ أَحَدٍ يَصْبِرُ إِذْ ذَاكَ، وَلِذَلِكَ قِيلَ: يَجِبُ عَلَى كُلِّ عَاقِلٍ أَنْ يَلْتَزِمَ عِنْدَ الْمُصِيبَةِ مَا لَا بُدَّ لِلْأَحْمَقِ مِنْهُ بَعْدَ ثَلَاثٍ.","w":"القرطبي","en":"Al-Qurtubi: but that is only with patience at the first shock, as al-Bukhari reported from Anas from the Prophet, peace be upon him: (Patience is only at the first shock). Muslim also reported it more fully. The meaning: the patience that is hard on the self and earns great reward is at the onset and heat of the calamity, for it shows strength of heart and firmness in the station of patience; once the heat of the calamity cools, everyone is patient. So it was said that every sensible person should hold at the calamity to what the foolish must come to after three days."}]},{"id":"musiba","ch":"bala","t":"«ما أصاب من مصيبة»: لكيلا تأسوا على ما فاتكم","e":"أن كل مصيبة مكتوبة، وأن الفرح شكر والحزن صبر.","ay":[[57,22,23]],"q":[{"bk":"saadi","s":57,"ay":22,"x":"وأخبر الله عبادَه بذلك لأجل أن تتقرَّرَ هذه القاعدة عندهم، ويبنوا عليها ما أصابهم من الخير والشرِّ؛ فلا يأسَوْا، ويحزنوا على ما فاتهم، مما طَمِحَتْ له أنفسُهم وتشوَّفوا إليه؛ لعلمِهِم أنَّ ذلك مكتوبٌ في اللوح المحفوظ، لا بدَّ من نفوذه ووقوعه؛ فلا سبيل إلى دفعِهِ، ولا يفرحوا بما آتاهم الله فرحَ بَطَرٍ وأشَرٍ؛ لعلمهم أنَّهم ما أدركوه بحولهم وقوَّتهم، وإنَّما أدركوه بفضل الله ومنِّه، فيشتغلوا بشكر مَنْ أولى النِّعم ودفع النِّقم، ولهذا قال:{واللهُ لا يحبُّ كلَّ مختالٍ فخورٍ}؛ أي: متكبِّر فظٍّ غليظٍ معجبٍ بنفسه فخورٍ بنعم الله ينسبها إلى نفسه وتُطغيه وتُلهيه؛ كما قال تعالى:{وإذا أذَقۡناه رحمةً منَّا قال إنَّما أوتيتُهُ على علم بَلۡ هي فتنةٌ}.","w":"السعدي","en":"Al-Sa'di: Allah told His servants this so this rule is settled with them and they build on it what befalls them of good and ill: they do not despair and grieve over what they missed, knowing it is written in the Preserved Tablet and bound to happen, and they do not exult over what Allah gave in arrogance, knowing they did not reach it by their own strength but by Allah's favour, so they busy themselves with thanking the Giver. Hence He said: \"and Allah does not love every arrogant, boastful one.\""},{"bk":"ibnkathir","s":57,"ay":22,"x":"وَقَالَ عِكْرِمَةُ: لَيْسَ أَحَدٌ إِلَّا وَهُوَ يَفْرَحُ وَيَحْزَنُ، وَلَكِنِ اجْعَلُوا الفَرَح شُكْرًا وَالْحُزْنَ صَبْرًا.","w":"ابن كثير","en":"Ibn Kathir: Ikrimah said: there is no one who does not rejoice and grieve, but make your joy gratitude and your grief patience."}]},{"id":"adha","ch":"bala","t":"«لتبلون في أموالكم وأنفسكم»: الصبر على أذى أهل الكتاب والمشركين","e":"الابتلاء في الأموال والأنفس والصبر على أذى الظالمين.","ay":[[3,186,186]],"q":[{"bk":"saadi","s":3,"ay":186,"x":"ومنها: أنه أخبرهم بذلك لتتوطن نفوسهم على وقوع ذلك والصبر عليه إذا وقع لأنهم قد استعدوا لوقوعه فيهون عليهم حمله وتخف عليهم مؤنته ويلجؤون إلى الصبر والتقوى، ولهذا قال:{وإن تصبروا وتتقوا}؛ أي:إن تصبروا على ما نالكم في أموالكم وأنفسكم من الابتلاء والامتحان وعلى أذية الظالمين وتتقوا الله في ذلك الصبر بأن تنووا به وجه الله والتقرب إليه ولم تتعدوا في صبركم الحد الشرعي من الصبر في موضع لا يحل لكم فيه الاحتمال بل وظيفتكم فيه الانتقام من أعداء الله.{فإن ذلك من عزم الأمور}؛ أي: من الأمور التي يعزم عليها وينافس فيها ولا يوفق لها إلا أهل العزائم والهمم العالية، كما قال تعالى:{وما يلقاها إلا الذين صبروا وما يلقاها إلا ذو حظ عظيم}.","w":"السعدي","en":"Al-Sa'di: He told them this so their souls prepare for it and for patience when it happens, for having prepared, bearing it becomes easy and its burden light, and they turn to patience and piety. Hence: \"And if you are patient and fear Allah\": if you are patient over what befalls your wealth and selves of testing and over wrongdoers' harm, and fear Allah in that patience by intending Allah's face and nearness, without exceeding the lawful limit of patience in a place where one may not bear it but should rather fight Allah's enemies, \"then that is of the matters of resolve\", which only people of resolve and high aspirations are granted."}]},{"id":"baas","ch":"bala","t":"«والصابرين في البأساء والضراء وحين البأس»","e":"وصف الصابرين في البأساء والضراء وحين البأس.","ay":[[2,177,177]],"q":[{"bk":"saadi","s":2,"ay":177,"x":"أي: الفقر لأن الفقير يحتاج إلى الصبر من وجوه كثيرة لكونه يحصل له من الآلام القلبية والبدنية المستمرة ما لا يحصل لغيره، فإن تنعم الأغنياء بما لا يقدر عليه تألم وإن جاع أو جاعت عياله تألم، وإن أكل طعاماً غير موافق لهواه تألم، وإن عري أو كاد تألم، وإن نظر إلى ما بين يديه وما يتوهمه من المستقبل الذي يستعد له تألم، وإن أصابه البرد الذي لا يقدر على دفعه تألم، فكل هذه ونحوها مصائب يؤمر بالصبر عليها والاحتساب ورجاء الثواب من الله عليها {والضراء}؛ أي: المرض على اختلاف أنواعه من حمى وقروح ورياح ووجع عضو حتى الضرس والإصبع ونحو ذلك فإنه يحتاج إلى الصبر على ذلك، لأن النفس تضعف والبدنَ يألم وذلك في غاية المشقة على النفوس …","w":"السعدي","en":"Al-Sa'di: that is, poverty, for the poor need patience in many ways: lasting pains of heart and body others do not have. If wealthy people enjoy what he cannot afford he is pained; if he or his family go hungry he is pained; if he eats food against his desire he is pained; if he lacks clothing he is pained; if he looks at the future he must prepare for he is pained; if cold strikes him and he cannot ward it off he is pained. All these are calamities he is commanded to bear patiently, seeking reward from Allah. Then \"adversity\": illness of all kinds, fevers, sores, winds, pains of a limb, even a tooth or finger, for the self weakens and the body aches, which is extremely hard on souls."}]},{"id":"rabbaniyun","ch":"bala","t":"«وكأيّن من نبي قاتل معه ربيون كثير»: الثبات في الشدة","e":"صبر أتباع الأنبياء على القتل والجراح وثباتهم ودعاؤهم.","ay":[[3,146,148]],"q":[{"bk":"saadi","s":3,"ay":146,"x":"هذا تسلية للمؤمنين وحثٌّ على الاقتداء بهم والفعل كفعلهم، وأن هذا أمر قد كان متقدماً لم تزل سنة الله جارية بذلك، فقال:{وكأين من نبي}؛ أي: وكم من نبي {قاتل معه ربيون كثير}؛ أي: جماعات كثيرون من أتباعهم الذين قد ربتهم الأنبياء بالإيمان والأعمال الصالحة فأصابهم قتل وجراح وغير ذلك، {فما وهنوا لما أصابهم في سبيل الله وما ضعفوا وما استكانوا}؛ أي: ما ضعفت قلوبهم، ولا وهنت أبدانهم، ولا استكانوا؛ أي: ذلُّوا لعدوهم، بل صبروا وثبتوا وشجعوا أنفسهم، ولهذا قال:{والله يحب الصابرين}.","w":"السعدي","en":"Al-Sa'di: this is a consolation to the believers and an urging to follow them: \"how many a prophet fought with many devoted men\", whom the prophets raised with faith and good deeds, and they suffered killing, wounds and more; \"yet they did not weaken for what struck them in Allah's way, nor grow feeble, nor submit\", their hearts did not weaken, their bodies did not tire and they did not humble themselves to their enemy, but were patient, firm and encouraged themselves; so He said: \"and Allah loves the patient.\""},{"bk":"saadi","s":3,"ay":146,"x":"ثم إنهم لم يتكلوا على ما بذلوا جهدهم به من الصبر، بل اعتمدوا على الله، وسألوه أن يثبت أقدامهم عند ملاقاة الأعداء الكافرين، وأن ينصرهم عليهم، فجمعوا بين الصبر وترك ضده، والتوبة والاستغفار والاستنصار بربهم، لا جرم أن الله نصرهم، وجعل لهم العاقبة في الدنيا والآخرة ولهذا قال: {148}{فآتاهم الله ثواب الدنيا} من النصر والظفر والغنيمة {وحُسن ثواب الآخرة} وهو الفوز برضا ربهم والنعيم المقيم الذي قد سلم من جميع المنكدات، وما ذاك إلا أنهم أحسنوا له الأعمال فجازاهم بأحسن الجزاء، فلهذا قال:{والله يحب المحسنين} في عبادة الخالق ومعاملة الخلق، ومن الإحسان أن يفعل عند جهاد الأعداء كفعل هؤلاء المؤمنين.","w":"السعدي","en":"Al-Sa'di: they did not rely on the patience they strove with, but depended on Allah and asked Him to make their feet firm when meeting the disbelieving enemy and to give them victory. They combined patience, leaving its opposite, repentance, seeking forgiveness and seeking help from their Lord, so Allah helped them and gave them the outcome in this world and the next. So He said: \"So Allah gave them the reward of this world\", victory, triumph and spoils, \"and the best reward of the Hereafter\", winning their Lord's pleasure and lasting bliss free of all vexations, because they did their deeds well and He repaid them with the best repayment, for \"Allah loves the doers of good\"."}]},{"id":"thabat","ch":"bala","t":"«واصبروا إن الله مع الصابرين»: الثبات عند اللقاء","e":"الثبات عند لقاء العدو وذكر الله، وبيان كون الله مع الصابرين.","ay":[[8,45,46],[8,65,66]],"q":[{"bk":"saadi","s":8,"ay":46,"x":"أي: تدركون ما تطلبون من الانتصار على أعدائكم؛ فالصبرُ والثبات والإكثار من ذِكْر الله من أكبر الأسباب للنصر.","w":"السعدي","en":"Al-Sa'di: that is, you attain what you seek of victory over your enemies; patience, steadfastness and much remembrance of Allah are among the greatest causes of victory."},{"bk":"saadi","s":8,"ay":65,"x":"والثاني: تقييدُ ذلك العدد أن يكونوا صابرين؛ بأن يكونوا متدرِّبين على الصبر، ومفهوم هذا أنَّهم إذا لم يكونوا صابرين؛ فإنه يجوز لهم الفرار، ولو أقل من مثليهم، إذا غَلَبَ على ظنِّهم الضرر؛ كما تقتضيه الحكمة الإلهية.","w":"السعدي","en":"Al-Sa'di: the second point is that the number is conditioned on their being patient, that is, trained in patience, and by implication if they are not patient, they may flee even from fewer than twice their number when they think harm is likely, as divine wisdom requires."}]},{"id":"afragh","ch":"bala","t":"«ربنا أفرغ علينا صبراً»: الدعاء بالصبر","e":"دعاء الصبر الذي دعا به أتباع موسى وسحرة فرعون.","ay":[[2,250,250],[7,126,126]],"q":[{"bk":"saadi","s":7,"ay":137,"x":"ثم دعوا الله أن يثبِّتهم ويصبِّرهم، فقالوا:{ربَّنا أفرغۡ}؛ أي: أفض {عليۡنا صبراً}؛ أي: عظيماً كما يدلُّ عليه التنكير؛ لأنَّ هذه محنة عظيمة تؤدي إلى ذهاب النفس، فيحتاج فيها من الصبر إلى شيء كثير؛ ليثبت الفؤاد ويطمئن المؤمن على إيمانِهِ ويزول عنه الانزعاج الكثير.","w":"السعدي","en":"Al-Sa'di: then they asked Allah to make them firm and patient and said: \"Our Lord, pour upon us patience\", that is, pour out upon us great patience, as the indefinite form indicates, because this is a great trial that may lead to losing one's life, and one needs much patience in it so the heart is firm, the believer is at ease about his faith and great alarm leaves him."}]},{"id":"yaqub","ch":"anbiya","t":"يعقوب عليه السلام: «فصبر جميل والله المستعان»","e":"قول يعقوب عليه السلام لما فقد ابنيه.","ay":[[12,18,18],[12,83,86]],"q":[{"bk":"saadi","s":12,"ay":83,"x":"فلما رجعوا إلى أبيهم وأخبروه بهذا الخبر؛ اشتدَّ حزنُه وتضاعف كَمَدُهُ واتَّهمهم أيضاً في هذه القضيَّة كما اتَّهمهم في الأولى و {قال بل سوَّلَتۡ لكم أنفسُكم أمراً فصبرٌ جميلٌ}؛ أي: ألجأ في ذلك إلى الصبر الجميل الذي لا يصحَبُه تسخُّط ولا جزعٌ ولا شكوى للخلق.","w":"السعدي","en":"Al-Sa'di: when they returned to their father and told him this news, his grief intensified and his sorrow multiplied, and he suspected them in this matter as he had in the first, and said: \"Rather, your souls have enticed you to something, so patience is beautiful\", that is, I turn to beautiful patience, which is accompanied by no resentment, impatience or complaint to people."}]},{"id":"ayyub","ch":"anbiya","t":"أيوب عليه السلام: «إنا وجدناه صابراً نعم العبد»","e":"ثناء الله على أيوب بالصبر على الضر وجعله عبرة.","ay":[[21,83,84],[38,41,44]],"q":[{"bk":"saadi","s":38,"ay":41,"x":"أي: أيوب {صابراً}؛ أي: ابتليناه بالضُّرِّ العظيم فصبر لوجه الله تعالى.","w":"السعدي","en":"Al-Sa'di: that is, Job was patient: We tested him with severe harm and he was patient for Allah's sake."},{"bk":"saadi","s":21,"ay":83,"x":"أي: جعلناه عبرةً للعابدين الذين ينتفعون بالصبرِ؛ فإذا رأوا ما أصابه من البلاءِ، ثم ما أثابه بعد زواله، ونظروا السببَ؛ وجدوه الصبر، ولهذا أثنى الله عليه به في قوله:{إنَّا وَجَدۡناه صابراً نعم العبدُ إنَّه أوابٌ}، فجعلوه أسوةً وقدوةً عندما يصيبُهُم الضرُّ.","w":"السعدي","en":"Al-Sa'di: that is, We made him a lesson for the worshippers who benefit from patience: when they see what struck him of affliction, then what Allah gave him after it ended, and look for the cause, they find it was patience. Hence Allah praised him for it: \"We found him patient, an excellent servant; he was ever turning back,\" and they take him as an example and model when harm strikes them."}]},{"id":"ulu","ch":"anbiya","t":"«فاصبر كما صبر أولو العزم من الرسل»","e":"الأمر بالاقتداء بأولي العزم من الرسل في الصبر على التكذيب.","ay":[[46,35,35],[40,55,55],[6,34,34]],"q":[{"bk":"saadi","s":46,"ay":35,"x":"ثم أمر تعالى رسوله أن يصبِرَ على أذيَّة المكذِّبين المعادين له، وأن لا يزال داعياً لهم إلى الله، وأن يقتديَ بصبرِ أولي العزم من المرسَلين سادات الخَلْق أولي العزائم والهِمَم العالية، الذين عَظُم صَبْرُهم وتمَّ يقينُهم؛ فهم أحقُّ الخلق بالأسوة بهم والقفو لآثارهم والاهتداء بمنارِهِم، فامتثل - صلى الله عليه وسلم - لأمر ربِّه، فصبر صبراً لم يصبِرْه نبيٌّ قبله، حتى رماه المعادون له عن قوسٍ واحدةٍ، وقاموا جميعاً بصدِّه عن الدَّعوة إلى الله، وفعلوا ما يمكنهم من المعاداة والمحاربة، وهو - صلى الله عليه وسلم - لم يزل صادعاً بأمر الله، مقيماً على جهاد أعداء الله، صابراً على ما ينالُه من الأذى، حتى مكَّن الله له في الأرض، وأظهر دينَه على سائر الأديان وأمَّته على الأمم …","w":"السعدي","en":"Al-Sa'di: then Allah commanded His Messenger to be patient over the harm of the deniers who opposed him, to keep calling them to Allah and to follow the patience of the resolute messengers, the masters of creation with high resolve, whose patience was great and whose certainty was complete, so they are the most deserving to follow. He obeyed his Lord and was patient as no prophet before him, until his enemies shot at him from one bow and all rose to block him from calling to Allah and did all they could in hostility and war, while he kept proclaiming Allah's command and striving against Allah's enemies, patient with the harm that reached him, until Allah gave him power in the land and made his religion prevail over all religions and his nation over nations."},{"bk":"saadi","s":6,"ay":34,"x":"{ولقد كُذِّبَتۡ رسلٌ من قبلك فصبروا على ما كُذِّبوا وأوذوا حتى أتاهم نصرُنا}: فاصبرْ كما صبروا؛ تظفرْ كما ظفروا، {ولقد جاءك من نبإِ المرسلين}؛ ما به يَثْبُتُ فؤادُك، ويطمئنُّ به قلبك.","w":"السعدي","en":"Al-Sa'di: \"Messengers before you were denied, but they were patient over being denied and harmed until Our help came to them\": so be patient as they were and you will triumph as they did; \"and there has come to you of the news of the messengers\" what makes your heart firm and at peace."}]},{"id":"rusul","ch":"anbiya","t":"«ولنصبرن على ما آذيتمونا»: صبر الرسل على أقوامهم","e":"قول الرسل لأقوامهم: ولنصبرن على ما آذيتمونا.","ay":[[14,12,12]],"q":[{"bk":"saadi","s":14,"ay":12,"x":"ولنستمرنَّ على دعوتِكم ووعظِكم وتذكيركم، ولا نبالي بما يأتينا منكم من الأذى؛ فإنَّا سنوطِّن أنفسنا على ما ينالنا منكم من الأذى؛ احتساباً للأجر ونصحاً لكم، لعلَّ الله أن يهدِيَكم مع كثرة التذكير.","w":"السعدي","en":"Al-Sa'di: we will keep calling you, advising and reminding you, not caring about the harm that comes from you, for we will prepare ourselves for what we get from you of harm, seeking reward and out of sincere advice for you, perhaps Allah will guide you through much reminding."}]},{"id":"khidr","ch":"anbiya","t":"موسى والخضر: «إنك لن تستطيع معي صبراً»","e":"قصة موسى مع الخضر وعلاقة الصبر بالعلم والإحاطة.","ay":[[18,67,69],[18,78,78],[18,82,82]],"q":[{"bk":"saadi","s":18,"ay":67,"x":"ولهذا قال: {وكيفَ تصبر على ما لم تُحِطۡ به خُبۡراً}؛ أي: كيف تصبر على أمرٍ ما أحطتَ بباطنه وظاهره وعلمتَ المقصودَ منه ومآله.","w":"السعدي","en":"Al-Sa'di: so he said: \"And how can you be patient over what you do not encompass in knowledge?\", that is, how can you be patient over a matter whose inside and outside you have not grasped and whose purpose and outcome you do not know."},{"bk":"saadi","s":18,"ay":67,"x":"ومنها: أن السبب الكبير لحصول الصبر إحاطةُ الإنسان علماً وخبرةً بذلك الأمر الذي أمِرَ بالصبر عليه، وإلاَّ؛ فالذي لا يدريه أو لا يدري غايته ولا نتيجته ولا فائدته وثمرته ليس عنده سببُ الصبر؛ لقوله:{وكيف تصبِرُ على ما لم تُحِطۡ به خُبۡراً}؛ فجعل الموجب لعدم صبرِهِ عدم إحاطته خُبراً بالأمر.","w":"السعدي","en":"Al-Sa'di: and among the lessons: the great cause of patience is a person's grasp of knowledge and understanding of the matter he is commanded to be patient over. One who does not know it, or its end, result and benefit, has no cause for patience, as He said: \"And how can you be patient over what you do not encompass in knowledge?\", making the cause of his lack of patience his not grasping the matter."}]},{"id":"ismail","ch":"anbiya","t":"إسماعيل عليه السلام: «ستجدني إن شاء الله من الصابرين»","e":"قول إسماعيل لأبيه وعده من نفسه الصبر مقروناً بمشيئة الله.","ay":[[37,100,102],[21,85,85]],"q":[{"bk":"saadi","s":37,"ay":102,"x":"فإنَّ أمر الله تعالى لا بدَّ من تنفيذِهِ، فقال إسماعيلُ صابراً محتسباً مرضياً لربِّه وبارًّا بوالده:{يا أبتِ افۡعَلۡ ما تُؤۡمَرۡ}؛ أي: امضِ لما أمَرَكَ الله، {سَتَجِدُني إن شاء الله من الصابرينَ}: أخبر أباه أنَّه موطِّنٌ نفسَه على الصبر، وقَرَنَ ذلك بمشيئة الله تعالى؛ لأنَّه لا يكون شيءٌ بدون مشيئةِ الله. {103}{فلمَّا أسۡلَما}؛ أي: إبراهيم وابنه إسماعيل: إبراهيم جازماً بقتل ابنه وثمرةِ فؤادِهِ امتثالاً لأمر ربِّه وخوفاً من عقابه، والابن قد وطَّن نفسه على الصبر، وهانتْ عليه في طاعة ربِّه ورضا والده، {وَتَلَّه للجبينِ}؛ أي: تلَّ إبراهيمُ إسماعيلَ على جبينِهِ لِيُضْجِعَه فيذبَحَه، وقد انكبَّ لوجهِهِ؛ لئلاَّ ينظرَ وقت الذبح إلى وجهِهِ.","w":"السعدي","en":"Al-Sa'di: Allah's command must be carried out, so Ishmael said, patient, seeking reward, pleasing his Lord and dutiful to his father: \"O my father, do as you are commanded\", go ahead with what Allah commanded you, \"you will find me, if Allah wills, among the patient\": he told his father he had prepared himself for patience, and bound it to Allah's will, since nothing happens without it. Then, when both submitted, Abraham firm in slaying his son, the fruit of his heart, in obedience to his Lord and fearing His punishment, and the son having prepared himself for patience, finding it easy in obeying his Lord and pleasing his father, \"and he laid him on his forehead\", Abraham laid Ishmael on his temple to lay him down to slaughter him, face down, so he would not look at his face when slaughtering."}]},{"id":"yunus","ch":"anbiya","t":"«ولا تكن كصاحب الحوت»: العجلة وفوات الصبر","e":"النهي عن مشابهة صاحب الحوت في عدم الصبر.","ay":[[68,48,50]],"q":[{"bk":"saadi","s":68,"ay":48,"x":"وقوله:{ولا تكن كصاحب الحوتِ}: وهو يونس بن متى عليه الصلاة والسلام؛ أي: ولا تشابِهه في الحال التي أوصلَتْه وأوجبت له الانحباس في بطن الحوت، وهو عدم صبره على قومِهِ الصبرَ المطلوب منه وذَهابُه مغاضباً لربِّه، حتى ركب [في] البحر، فاقترع أهل السفينة حين ثقلت بأهلها أيُّهم يلقون؛ لكي تَخِفَّ بهم، فوقعت القرعةُ عليه، فالتقمه الحوتُ وهو مليمٌ.","w":"السعدي","en":"Al-Sa'di: \"and do not be like the man of the fish\", Jonah son of Matta, peace be upon him: do not resemble him in the state that led to his confinement in the belly of the fish, namely his lack of the required patience with his people and his leaving angry with his Lord until he boarded the sea. The ship's people cast lots when it grew heavy to see whom to throw so it would lighten; the lot fell on him and the fish swallowed him while he was blameworthy."},{"bk":"saadi","s":68,"ay":48,"x":"فامتثل نبيُّنا محمدٌ - صلى الله عليه وسلم - أمر الله ، فصبر لحكم ربِّه صبراً لا يدركه [فيه] أحدٌ من العالمين، فجعل الله له العاقبة، والعاقبةُ للمتقين، ولم يبلغ أعداؤه فيه إلاَّ ما يسوؤهم، حتى إنَّهم حرصوا على أن يُزْلِقوه {بأبصارهم}؛ أي: يصيبوه بأعينهم من حسدهم وحنقهم وغيظهم.","w":"السعدي","en":"Al-Sa'di: our Prophet Muhammad, peace be upon him, obeyed Allah's command and was patient with his Lord's decree as no one in the worlds could, so Allah gave him the good outcome, and the outcome is for the pious. His enemies reached nothing of him but what grieved them, even so far that they were keen to make him slip \"with their eyes\", that is, to afflict him with the evil eye from their envy, spite and rage."}]},{"id":"lihukm","ch":"anbiya","t":"«واصبر لحكم ربك فإنك بأعيننا»","e":"الأمر بالصبر لحكم الله والاستعانة عليه بالذكر والعبادة.","ay":[[52,48,48],[16,127,128]],"q":[{"bk":"saadi","s":52,"ay":48,"x":"ولمَّا بيَّن تعالى الحجج والبراهين على بطلان أقوال المكذِّبين؛ أمر رسوله - صلى الله عليه وسلم - أن لا يعبأ بهم شيئاً، وأنْ يصبِرَ لحكم ربِّه القدريِّ والشرعيِّ؛ بلزومه والاستقامة عليه، وَوَعَدَهُ الله الكفاية بقوله:{فإنَّك بأعيننا}؛ أي: بمرأى منَّا وحفظٍ واعتناءٍ بأمرك، وأمره أن يستعين على الصبر بالذكر والعبادة، فقال:{وسبِّح بحمد ربِّك حين تقومُ}؛ [أي]: من الليل؛ ففيه الأمر بقيام الليل، أو حين تقومُ إلى الصلوات الخمس؛ بدليل قوله:{ومن الليل فسبِّحۡه وإدۡبارَ النُّجومِ}؛ أي: آخر الليل، ويدخل فيه صلاة الفجر.","w":"السعدي","en":"Al-Sa'di: after showing the proofs against the deniers' claims, Allah commanded His Messenger not to heed them at all and to be patient with his Lord's decree of fate and law, keeping to it and standing firm on it, and promised him sufficiency: \"for you are before Our eyes\", under Our sight, protection and care. He commanded him to seek help for patience through remembrance and worship: \"and glorify your Lord with praise when you rise\", from sleep at night, which includes night prayer, or when you rise for the five prayers, and \"during part of the night glorify Him and at the setting of the stars\", the end of the night, which includes the dawn prayer."},{"bk":"saadi","s":16,"ay":127,"x":"ثم أمر رسوله بالصبر على دعوةِ الخلق إلى الله والاستعانة بالله على ذلك وعدم الاتِّكال على النفس، فقال:{واصۡبِرۡ وما صَبۡرُكَ إلاَّ بالله}: هو الذي يُعينك عليه ويُثَبِّتُك.","w":"السعدي","en":"Al-Sa'di: then He commanded His Messenger to be patient in calling people to Allah, to seek Allah's help in that and not to rely on himself, so He said: \"Be patient, and your patience is only through Allah\": He is the one who helps you in it and makes you firm."}]},{"id":"hisab","ch":"jaza","t":"«إنما يوفى الصابرون أجرهم بغير حساب»","e":"أن أجر الصابرين غير محسوب ولا موزون.","ay":[[39,10,10]],"q":[{"bk":"ibnkathir","s":39,"ay":10,"x":"وَقَوْلُهُ: ﴿إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ﴾ قَالَ الْأَوْزَاعِيُّ: لَيْسَ يُوزَنُ لَهُمْ وَلَا يُكَالُ ، إِنَّمَا يُغْرَفُ لَهُمْ غَرْفًا.","w":"ابن كثير","en":"Ibn Kathir: of His words \"the patient will be given their reward without measure\", al-Awza'i said: it is not weighed or measured for them; it is poured out for them in handfuls."},{"bk":"qurtubi","s":39,"ay":10,"x":"وَقَالَ مَالِكُ بْنُ أَنَسٍ فِي قَوْلِهِ: \"إِنَّما يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسابٍ\" قَالَ: هُوَ الصَّبْرُ عَلَى فَجَائِعِ الدُّنْيَا وَأَحْزَانِهَا.","w":"القرطبي","en":"Al-Qurtubi: Malik ibn Anas said about \"the patient will be given their reward without measure\": it is patience at the calamities and sorrows of this world."}]},{"id":"ghurfa","ch":"jaza","t":"«أولئك يجزون الغرفة بما صبروا»","e":"جزاء الصابرين بالغرفة والجنة والحرير.","ay":[[25,75,76],[76,12,12]],"q":[{"bk":"saadi","s":25,"ay":75,"x":"ولهذا لما كانت هِمَمُهُم ومطالِبُهم عاليةً، كان الجزاء من جنس العمل، فجازاهم بالمنازل العاليات، فقال:{أولئك يُجۡزَوۡنَ الغرفةَ بما صبروا}؛ أي: المنازل الرفيعة والمساكن الأنيقة الجامعة لكلِّ ما يشتهَى وتلذُّه الأعين، وذلك بسبب صبرِهِم نالوا ما نالوا؛ كما قال تعالى:{والملائكةُ يَدۡخُلون عليهم مِن كلِّ بابٍ.","w":"السعدي","en":"Al-Sa'di: since their aspirations and aims were high, the repayment matched the deed, so He repaid them with lofty stations and said: \"Those will be rewarded with the highest place for their patience\", the lofty ranks and elegant dwellings containing all that is desired and delights the eyes; they attained what they did because of their patience, as Allah said: \"And the angels will enter upon them from every gate.\""},{"bk":"saadi","s":76,"ay":24,"x":"{وجزاهم بما صبروا}: على طاعته فعملوا ما أمكنهم منها، وعن معاصيه فتركوها، وعلى أقداره المؤلمة فلم يتسخَّطوها {جنَّةً}: جامعةً لكلِّ نعيمٍ سالمةً من كلِّ مكدِّرٍ ومنغِّص، {وحريراً}؛ كما قال تعالى:{ولباسُهم فيها حريرٌ}: ولعلَّ اللهَ إنَّما خصَّ الحريرَ لأنَّه لباسهم الظَّاهر الدالُّ على حال صاحبه.","w":"السعدي","en":"Al-Sa'di: \"and He rewarded them for their patience\": upon His obedience so they did what they could of it, away from His disobedience so they left it, and upon His painful decrees without resenting them, \"with a garden\" containing every bliss, free of every trouble, \"and silk\", as He said \"and their clothing therein is silk\"; perhaps Allah singled out silk because it is their outer clothing that shows the state of its wearer."}]},{"id":"marratayn","ch":"jaza","t":"«يؤتون أجرهم مرتين بما صبروا»","e":"أجر الصابرين على الإيمان مرتين.","ay":[[28,54,54]],"q":[{"bk":"saadi","s":28,"ay":54,"x":"{أولئك}: الذين آمنوا بالكتابين {يؤتَوۡن أجۡرَهُم مرتينِ}: أجراً على الإيمان الأوَّل، وأجراً على الإيمان الثاني؛ {بما صَبَروا}: على الإيمان، وثبتوا على العمل، فلم تُزَعْزِعْهم عن ذلك شبهةٌ، ولا ثناهم عن الإيمان رياسةٌ ولا شهوة.","w":"السعدي","en":"Al-Sa'di: \"those\" who believed in both Books \"will be given their reward twice\": a reward for the first faith and a reward for the second, \"for what they were patient\" upon faith, standing firm on deeds, no doubt unsettling them and no leadership or desire turning them from faith."}]},{"id":"ajr96","ch":"jaza","t":"«ولنجزين الذين صبروا أجرهم بأحسن ما كانوا يعملون»","e":"وعد الله الصابرين بأحسن ما كانوا يعملون.","ay":[[16,96,96]],"q":[{"bk":"saadi","s":16,"ay":96,"x":"على طاعة الله وعن معصيته، وفَطَموا أنفسَهم عن الشهوات الدنيويَّة المضرَّة بدينهم؛ {أجۡرَهم بأحسنِ ما كانوا يعملون}: الحسنةُ بعشر أمثالها إلى سبعمائة ضعف إلى أضعاف كثيرة؛ فإنَّ الله لا يضيع أجر من أحسن عملاً.","w":"السعدي","en":"Al-Sa'di: those patient upon Allah's obedience and away from His disobedience, who weaned their souls from worldly desires harmful to their religion, \"We will surely give them their reward by the best of what they used to do\": a good deed tenfold up to seven hundredfold and many times over, for Allah does not waste the reward of one who does good."}]},{"id":"salam","ch":"jaza","t":"«سلام عليكم بما صبرتم فنعم عقبى الدار»","e":"سلام الملائكة على الصابرين ابتغاء وجه الله.","ay":[[13,22,24]],"q":[{"bk":"saadi","s":13,"ay":22,"x":"{والذين صبروا}: على المأمورات بالامتثال، وعن المنهيَّات بالانكفاف عنها والبعد منها، وعلى أقدار الله المؤلمة بعدم تسخُّطها، ولكن بشرط أن يكون ذلك الصبر {ابتغاءَ وجهِ ربِّهم}: لا لغير ذلك من المقاصد والأغراض الفاسدة؛ فإنَّ هذا الصبر النافع، الذي يَحْبِسُ به العبد نفسه طلباً لمرضاة ربِّه ورجاءً للقرب منه والحظوة بثوابه، وهو الصبر الذي من خصائص أهل الإيمان، وأما الصبر المشترك الذي غايتُهُ التجلُّد ومنتهاه الفخر؛ فهذا يصدُرُ من البَرِّ والفاجر والمؤمن والكافر؛ فليس هو الممدوح على الحقيقة.","w":"السعدي","en":"Al-Sa'di: \"and those who were patient\" upon commands by carrying them out, away from prohibitions by leaving them, and upon Allah's painful decrees by not resenting them, on condition that this patience is \"seeking the face of their Lord\", not for other corrupt aims; this is the beneficial patience that holds the servant back seeking his Lord's pleasure, hoping for nearness to Him and His reward, a mark of the people of faith. As for common patience whose end is toughness and pride, it comes from the righteous and wicked, believer and disbeliever, and is not truly praised."}]},{"id":"salawat","ch":"jaza","t":"«أولئك عليهم صلوات من ربهم ورحمة»","e":"بشارة الصابرين بصلوات الله ورحمته.","ay":[[2,155,157]],"q":[{"bk":"qurtubi","s":2,"ay":155,"x":"قَوْلُهُ تَعَالَى: ﴿وَبَشِّرِ الصَّابِرِينَ﴾ أَيْ بِالثَّوَابِ عَلَى الصَّبْرِ. وَالصَّبْرُ أَصْلُهُ الْحَبْسُ، وَثَوَابُهُ غَيْرُ مُقَدَّرٍ، وَقَدْ تَقَدَّمَ .","w":"القرطبي","en":"Al-Qurtubi: \"and give good tidings to the patient\": that is, of reward for patience. Patience originally means holding back, and its reward is unmeasured, as already mentioned."}]},{"id":"imama","ch":"jaza","t":"«وجعلنا منهم أئمة يهدون بأمرنا لما صبروا»","e":"نيل الإمامة في الدين وتمكين المستضعفين بما صبروا.","ay":[[32,24,24],[7,137,137]],"q":[{"bk":"saadi","s":32,"ay":24,"x":"{وجَعَلۡنا منهم}؛ أي: من بني إسرائيل، {أئمة يهدونَ بأمرِنا}؛ أي: علماء بالشرع وطرق الهداية مهتدين في أنفسهم يهدون غيرهم بذلك الهدى؛ فالكتاب الذي أُنْزِل إليهم هدى، والمؤمنون به منهم على قسمين: أئمَّة يهدون بأمرِ الله، وأتباعٌ مهتدون بهم، والقسمُ الأول أرفع الدرجات بعد درجة النبوَّة والرسالة، وهي درجة الصديقين، وإنما نالوا هذه الدرجة العالية، {لما صبروا}: على التعلُّم والتعليم والدَّعوة إلى الله والأذى في سبيله، وكفُّوا نفوسَهم عن جِماحها في المعاصي واسترسالِها في الشهوات. {وكانوا بآياتِنا يوقِنونَ}؛ أي: وصلوا في الإيمان بآيات الله إلى درجة اليقين، وهو العلم التامُّ الموجب للعمل، وإنَّما وصلوا إلى درجة اليقين؛ لأنَّهم تعلَّموا تعلُّما صحيحاً، وأخذوا المسائل عن أدلتها المفيدة لليقين، فما زالوا يتعلَّمون المسائل، ويستدلُّون عليها بكثرة الدَّلائل، حتى وصلوا لذاك …","w":"السعدي","en":"Al-Sa'di: \"and We made among them leaders guiding by Our command\": scholars of the law and ways of guidance, guided themselves and guiding others; the Book sent to them is guidance. The believers among them are of two sorts: leaders who guide by Allah's command and followers guided by them. The first is the highest rank after prophethood and messengership, the rank of the truthful, and they attained it \"when they were patient\" in learning, teaching, calling to Allah and the harm in His way, and held their souls back from running into disobedience and giving way to desires; and \"they were certain of Our signs\", reaching certainty, the complete knowledge that drives action, because they learned correctly and took rulings from their proofs."},{"bk":"saadi","s":7,"ay":137,"x":"{وأورثنا القوم الذين كانوا يُسۡتَضۡعَفونَ}: في الأرض؛ أي: بني إسرائيل الذين كانوا خدمة لآل فرعون يسومونهم سوء العذاب، أورثهم الله {مشارقَ الأرض ومغاربها}: والمراد بالأرض ها هنا أرض مصر التي كانوا فيها مستضعفين أذلين؛ أي: ملَّكهم الله جميعها ومكَّنهم فيها، {التي باركنا فيها وتمَّتۡ كلمةُ ربك الحسنى على بني إسرائيل بما صبروا}: حين قال لهم موسى: {استعينوا باللَّهِ واصبِروا إنَّ الأرضَ للَّه يورِثها من يشاءُ من عباده والعاقبةُ للمتَّقين}، {ودمَّرۡنا ما كان يصنعُ فرعونُ وقومُهُ}: من الأبنية الهائلة والمساكن المزخرفة، {وما كانوا يعرِشون}: فتلك بيوتهم [خاوية] بما ظلموا إن في ذلك لآية لقوم يعلمون.","w":"السعدي","en":"Al-Sa'di: \"And We made inherit the people who were oppressed\" in the land, the Children of Israel, who were servants of Pharaoh's people, who inflicted terrible torment on them; Allah gave them \"the eastern and western parts of the land\", meaning the land of Egypt where they were weak and abased, and gave them power in it; \"and the best word of your Lord was fulfilled upon the Children of Israel for what they were patient\", when Moses told them: \"Seek help in Allah and be patient; the land belongs to Allah, He gives it as inheritance to whom He wills of His servants, and the outcome is for the pious.\" He destroyed what Pharaoh and his people built of huge structures and ornate dwellings."}]},{"id":"shakur","ch":"jaza","t":"«إن في ذلك لآيات لكل صبار شكور»","e":"أن الآيات ينتفع بها كل صبّار شكور.","ay":[[14,5,5],[31,31,31],[34,19,19],[42,33,33]],"q":[{"bk":"saadi","s":14,"ay":5,"x":"أي: في أيام الله على العباد، {لآياتٍ لكلِّ صبَّارٍ شكور}؛ أي: صبار في الضرَّاء والعسر والضيق، شكور على السراء والنعمة؛ فإنَّه يستدلُّ بأيامه على كمال قدرته وعميم إحسانه وتمام عدله وحكمته.","w":"السعدي","en":"Al-Sa'di: that is, in the days of Allah upon the servants, \"are signs for every patient, grateful one\", patient in hardship, difficulty and distress, grateful in ease and blessing, for he draws from His days proof of His perfect power, vast kindness and complete justice and wisdom."}]},{"id":"sabirat","ch":"jaza","t":"«والصابرين والصابرات»: مغفرة وأجر عظيم","e":"ذكر الصابرين والصابرات في أهل المغفرة والأجر العظيم.","ay":[[33,35,35]],"q":[{"bk":"ibnkathir","s":33,"ay":35,"x":"﴿وَالصَّابِرِينَ وَالصَّابِرَاتِ﴾ : هَذِهِ سَجِيّة الْأَثْبَاتِ، وَهِيَ الصَّبْرُ عَلَى الْمَصَائِبِ، وَالْعِلْمُ بِأَنَّ الْمَقْدُورَ كَائِنٌ لَا مَحَالَةَ، وَتَلَقّي ذَلِكَ بِالصَّبْرِ وَالثَّبَاتِ، وَإِنَّمَا الصَّبْرُ عِنْدَ الصَّدْمَةِ الْأُولَى، أَيْ: أَصْعَبُهُ فِي أَوَّلِ وَهْلَةٍ، ثُمَّ مَا بَعْدَهُ أَسْهَلُ مِنْهُ، وَهُوَ صِدْقُ السَّجِيَّةِ وَثَبَاتُهَا.","w":"ابن كثير","en":"Ibn Kathir: \"and the patient men and the patient women\": this is the character of the steady, which is patience at calamities, knowing that what is decreed will certainly be, and meeting it with patience and firmness; indeed patience is at the first shock, the hardest moment at first sight, then what follows is easier; it is truthfulness and steadiness of character."}]}],"ay":{"51":"وَٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ وَإِنَّهَا لَكَبِيرَةٌ إِلَّا عَلَى ٱلۡخَٰشِعِينَ","52":"ٱلَّذِينَ يَظُنُّونَ أَنَّهُم مُّلَٰقُواْ رَبِّهِمۡ وَأَنَّهُمۡ إِلَيۡهِ رَٰجِعُونَ","159":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱسۡتَعِينُواْ بِٱلصَّبۡرِ وَٱلصَّلَوٰةِۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ","161":"وَلَنَبۡلُوَنَّكُم بِشَيۡءٖ مِّنَ ٱلۡخَوۡفِ وَٱلۡجُوعِ وَنَقۡصٖ مِّنَ ٱلۡأَمۡوَٰلِ وَٱلۡأَنفُسِ وَٱلثَّمَرَٰتِۗ وَبَشِّرِ ٱلصَّٰبِرِينَ","162":"ٱلَّذِينَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةٞ قَالُوٓاْ إِنَّا لِلَّهِ وَإِنَّآ إِلَيۡهِ رَٰجِعُونَ","163":"أُوْلَٰٓئِكَ عَلَيۡهِمۡ صَلَوَٰتٞ مِّن رَّبِّهِمۡ وَرَحۡمَةٞۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُهۡتَدُونَ","183":"۞ لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ وَلَٰكِنَّ ٱلۡبِرَّ مَنۡ ءَامَنَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَٱلۡمَلَٰٓئِكَةِ وَٱلۡكِتَٰبِ وَٱلنَّبِيِّـۧنَ وَءَاتَى ٱلۡمَالَ عَلَىٰ حُبِّهِۦ ذَوِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَٱلسَّآئِلِينَ وَفِي ٱلرِّقَابِ وَأَقَامَ ٱلصَّلَوٰةَ وَءَاتَى ٱلزَّكَوٰةَ وَٱلۡمُوفُونَ بِعَهۡدِهِمۡ إِذَا عَٰهَدُواْۖ وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ","256":"وَلَمَّا بَرَزُواْ لِجَالُوتَ وَجُنُودِهِۦ قَالُواْ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","438":"وَكَأَيِّن مِّن نَّبِيّٖ قَٰتَلَ مَعَهُۥ رِبِّيُّونَ كَثِيرٞ فَمَا وَهَنُواْ لِمَآ أَصَابَهُمۡ فِي سَبِيلِ ٱللَّهِ وَمَا ضَعُفُواْ وَمَا ٱسۡتَكَانُواْۗ وَٱللَّهُ يُحِبُّ ٱلصَّٰبِرِينَ","439":"وَمَا كَانَ قَوۡلَهُمۡ إِلَّآ أَن قَالُواْ رَبَّنَا ٱغۡفِرۡ لَنَا ذُنُوبَنَا وَإِسۡرَافَنَا فِيٓ أَمۡرِنَا وَثَبِّتۡ أَقۡدَامَنَا وَٱنصُرۡنَا عَلَى ٱلۡقَوۡمِ ٱلۡكَٰفِرِينَ","440":"فَـَٔاتَىٰهُمُ ٱللَّهُ ثَوَابَ ٱلدُّنۡيَا وَحُسۡنَ ثَوَابِ ٱلۡأٓخِرَةِۗ وَٱللَّهُ يُحِبُّ ٱلۡمُحۡسِنِينَ","478":"۞ لَتُبۡلَوُنَّ فِيٓ أَمۡوَٰلِكُمۡ وَأَنفُسِكُمۡ وَلَتَسۡمَعُنَّ مِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَمِنَ ٱلَّذِينَ أَشۡرَكُوٓاْ أَذٗى كَثِيرٗاۚ وَإِن تَصۡبِرُواْ وَتَتَّقُواْ فَإِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ","492":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱصۡبِرُواْ وَصَابِرُواْ وَرَابِطُواْ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ","822":"وَلَقَدۡ كُذِّبَتۡ رُسُلٞ مِّن قَبۡلِكَ فَصَبَرُواْ عَلَىٰ مَا كُذِّبُواْ وَأُوذُواْ حَتَّىٰٓ أَتَىٰهُمۡ نَصۡرُنَاۚ وَلَا مُبَدِّلَ لِكَلِمَٰتِ ٱللَّهِۚ وَلَقَدۡ جَآءَكَ مِن نَّبَإِيْ ٱلۡمُرۡسَلِينَ","1079":"وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ رَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ","1090":"وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ وَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ بِمَا صَبَرُواْۖ وَدَمَّرۡنَا مَا كَانَ يَصۡنَعُ فِرۡعَوۡنُ وَقَوۡمُهُۥ وَمَا كَانُواْ يَعۡرِشُونَ","1204":"يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا لَقِيتُمۡ فِئَةٗ فَٱثۡبُتُواْ وَٱذۡكُرُواْ ٱللَّهَ كَثِيرٗا لَّعَلَّكُمۡ تُفۡلِحُونَ","1205":"وَأَطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ وَلَا تَنَٰزَعُواْ فَتَفۡشَلُواْ وَتَذۡهَبَ رِيحُكُمۡۖ وَٱصۡبِرُوٓاْۚ إِنَّ ٱللَّهَ مَعَ ٱلصَّٰبِرِينَ","1224":"يَٰٓأَيُّهَا ٱلنَّبِيُّ حَرِّضِ ٱلۡمُؤۡمِنِينَ عَلَى ٱلۡقِتَالِۚ إِن يَكُن مِّنكُمۡ عِشۡرُونَ صَٰبِرُونَ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُم مِّاْئَةٞ يَغۡلِبُوٓاْ أَلۡفٗا مِّنَ ٱلَّذِينَ كَفَرُواْ بِأَنَّهُمۡ قَوۡمٞ لَّا يَفۡقَهُونَ","1225":"ٱلۡـَٰٔنَ خَفَّفَ ٱللَّهُ عَنكُمۡ وَعَلِمَ أَنَّ فِيكُمۡ ضَعۡفٗاۚ فَإِن يَكُن مِّنكُم مِّاْئَةٞ صَابِرَةٞ يَغۡلِبُواْ مِاْئَتَيۡنِۚ وَإِن يَكُن مِّنكُمۡ أَلۡفٞ يَغۡلِبُوٓاْ أَلۡفَيۡنِ بِإِذۡنِ ٱللَّهِۗ وَٱللَّهُ مَعَ ٱلصَّٰبِرِينَ","1587":"وَٱصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ","1613":"وَجَآءُو عَلَىٰ قَمِيصِهِۦ بِدَمٖ كَذِبٖۚ قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٞۖ وَٱللَّهُ ٱلۡمُسۡتَعَانُ عَلَىٰ مَا تَصِفُونَ","1618":"وَرَٰوَدَتۡهُ ٱلَّتِي هُوَ فِي بَيۡتِهَا عَن نَّفۡسِهِۦ وَغَلَّقَتِ ٱلۡأَبۡوَٰبَ وَقَالَتۡ هَيۡتَ لَكَۚ قَالَ مَعَاذَ ٱللَّهِۖ إِنَّهُۥ رَبِّيٓ أَحۡسَنَ مَثۡوَايَۖ إِنَّهُۥ لَا يُفۡلِحُ ٱلظَّٰلِمُونَ","1619":"وَلَقَدۡ هَمَّتۡ بِهِۦۖ وَهَمَّ بِهَا لَوۡلَآ أَن رَّءَا بُرۡهَٰنَ رَبِّهِۦۚ كَذَٰلِكَ لِنَصۡرِفَ عَنۡهُ ٱلسُّوٓءَ وَٱلۡفَحۡشَآءَۚ إِنَّهُۥ مِنۡ عِبَادِنَا ٱلۡمُخۡلَصِينَ","1628":"قَالَ رَبِّ ٱلسِّجۡنُ أَحَبُّ إِلَيَّ مِمَّا يَدۡعُونَنِيٓ إِلَيۡهِۖ وَإِلَّا تَصۡرِفۡ عَنِّي كَيۡدَهُنَّ أَصۡبُ إِلَيۡهِنَّ وَأَكُن مِّنَ ٱلۡجَٰهِلِينَ","1678":"قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","1679":"وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ","1680":"قَالُواْ تَٱللَّهِ تَفۡتَؤُاْ تَذۡكُرُ يُوسُفَ حَتَّىٰ تَكُونَ حَرَضًا أَوۡ تَكُونَ مِنَ ٱلۡهَٰلِكِينَ","1681":"قَالَ إِنَّمَآ أَشۡكُواْ بَثِّي وَحُزۡنِيٓ إِلَى ٱللَّهِ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ","1685":"قَالُوٓاْ أَءِنَّكَ لَأَنتَ يُوسُفُۖ قَالَ أَنَا۠ يُوسُفُ وَهَٰذَآ أَخِيۖ قَدۡ مَنَّ ٱللَّهُ عَلَيۡنَآۖ إِنَّهُۥ مَن يَتَّقِ وَيَصۡبِرۡ فَإِنَّ ٱللَّهَ لَا يُضِيعُ أَجۡرَ ٱلۡمُحۡسِنِينَ","1728":"وَٱلَّذِينَ صَبَرُواْ ٱبۡتِغَآءَ وَجۡهِ رَبِّهِمۡ وَأَقَامُواْ ٱلصَّلَوٰةَ وَأَنفَقُواْ مِمَّا رَزَقۡنَٰهُمۡ سِرّٗا وَعَلَانِيَةٗ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ أُوْلَٰٓئِكَ لَهُمۡ عُقۡبَى ٱلدَّارِ","1729":"جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا وَمَن صَلَحَ مِنۡ ءَابَآئِهِمۡ وَأَزۡوَٰجِهِمۡ وَذُرِّيَّٰتِهِمۡۖ وَٱلۡمَلَٰٓئِكَةُ يَدۡخُلُونَ عَلَيۡهِم مِّن كُلِّ بَابٖ","1730":"سَلَٰمٌ عَلَيۡكُم بِمَا صَبَرۡتُمۡۚ فَنِعۡمَ عُقۡبَى ٱلدَّارِ","1754":"وَلَقَدۡ أَرۡسَلۡنَا مُوسَىٰ بِـَٔايَٰتِنَآ أَنۡ أَخۡرِجۡ قَوۡمَكَ مِنَ ٱلظُّلُمَٰتِ إِلَى ٱلنُّورِ وَذَكِّرۡهُم بِأَيَّىٰمِ ٱللَّهِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ","1761":"وَمَا لَنَآ أَلَّا نَتَوَكَّلَ عَلَى ٱللَّهِ وَقَدۡ هَدَىٰنَا سُبُلَنَاۚ وَلَنَصۡبِرَنَّ عَلَىٰ مَآ ءَاذَيۡتُمُونَاۚ وَعَلَى ٱللَّهِ فَلۡيَتَوَكَّلِ ٱلۡمُتَوَكِّلُونَ","1996":"مَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٖۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ","2026":"وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرٞ لِّلصَّٰبِرِينَ","2027":"وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ","2028":"إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ","2167":"وَٱصۡبِرۡ نَفۡسَكَ مَعَ ٱلَّذِينَ يَدۡعُونَ رَبَّهُم بِٱلۡغَدَوٰةِ وَٱلۡعَشِيِّ يُرِيدُونَ وَجۡهَهُۥۖ وَلَا تَعۡدُ عَيۡنَاكَ عَنۡهُمۡ تُرِيدُ زِينَةَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۖ وَلَا تُطِعۡ مَنۡ أَغۡفَلۡنَا قَلۡبَهُۥ عَن ذِكۡرِنَا وَٱتَّبَعَ هَوَىٰهُ وَكَانَ أَمۡرُهُۥ فُرُطٗا","2206":"قَالَ إِنَّكَ لَن تَسۡتَطِيعَ مَعِيَ صَبۡرٗا","2207":"وَكَيۡفَ تَصۡبِرُ عَلَىٰ مَا لَمۡ تُحِطۡ بِهِۦ خُبۡرٗا","2208":"قَالَ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ صَابِرٗا وَلَآ أَعۡصِي لَكَ أَمۡرٗا","2217":"قَالَ هَٰذَا فِرَاقُ بَيۡنِي وَبَيۡنِكَۚ سَأُنَبِّئُكَ بِتَأۡوِيلِ مَا لَمۡ تَسۡتَطِع عَّلَيۡهِ صَبۡرًا","2221":"وَأَمَّا ٱلۡجِدَارُ فَكَانَ لِغُلَٰمَيۡنِ يَتِيمَيۡنِ فِي ٱلۡمَدِينَةِ وَكَانَ تَحۡتَهُۥ كَنزٞ لَّهُمَا وَكَانَ أَبُوهُمَا صَٰلِحٗا فَأَرَادَ رَبُّكَ أَن يَبۡلُغَآ أَشُدَّهُمَا وَيَسۡتَخۡرِجَا كَنزَهُمَا رَحۡمَةٗ مِّن رَّبِّكَۚ وَمَا فَعَلۡتُهُۥ عَنۡ أَمۡرِيۚ ذَٰلِكَ تَأۡوِيلُ مَا لَمۡ تَسۡطِع عَّلَيۡهِ صَبۡرٗا","2314":"رَّبُّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا فَٱعۡبُدۡهُ وَٱصۡطَبِرۡ لِعِبَٰدَتِهِۦۚ هَلۡ تَعۡلَمُ لَهُۥ سَمِيّٗا","2479":"وَأۡمُرۡ أَهۡلَكَ بِٱلصَّلَوٰةِ وَٱصۡطَبِرۡ عَلَيۡهَاۖ لَا نَسۡـَٔلُكَ رِزۡقٗاۖ نَّحۡنُ نَرۡزُقُكَۗ وَٱلۡعَٰقِبَةُ لِلتَّقۡوَىٰ","2565":"۞ وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ","2566":"فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ","2567":"وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّٰبِرِينَ","2568":"وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ","2929":"أُوْلَٰٓئِكَ يُجۡزَوۡنَ ٱلۡغُرۡفَةَ بِمَا صَبَرُواْ وَيُلَقَّوۡنَ فِيهَا تَحِيَّةٗ وَسَلَٰمًا","2930":"خَٰلِدِينَ فِيهَاۚ حَسُنَتۡ مُسۡتَقَرّٗا وَمُقَامٗا","3305":"أُوْلَٰٓئِكَ يُؤۡتَوۡنَ أَجۡرَهُم مَّرَّتَيۡنِ بِمَا صَبَرُواْ وَيَدۡرَءُونَ بِٱلۡحَسَنَةِ ٱلسَّيِّئَةَ وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ","3330":"فَخَرَجَ عَلَىٰ قَوۡمِهِۦ فِي زِينَتِهِۦۖ قَالَ ٱلَّذِينَ يُرِيدُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا يَٰلَيۡتَ لَنَا مِثۡلَ مَآ أُوتِيَ قَٰرُونُ إِنَّهُۥ لَذُو حَظٍّ عَظِيمٖ","3331":"وَقَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ وَيۡلَكُمۡ ثَوَابُ ٱللَّهِ خَيۡرٞ لِّمَنۡ ءَامَنَ وَعَمِلَ صَٰلِحٗاۚ وَلَا يُلَقَّىٰهَآ إِلَّا ٱلصَّٰبِرُونَ","3485":"يَٰبُنَيَّ أَقِمِ ٱلصَّلَوٰةَ وَأۡمُرۡ بِٱلۡمَعۡرُوفِ وَٱنۡهَ عَنِ ٱلۡمُنكَرِ وَٱصۡبِرۡ عَلَىٰ مَآ أَصَابَكَۖ إِنَّ ذَٰلِكَ مِنۡ عَزۡمِ ٱلۡأُمُورِ","3499":"أَلَمۡ تَرَ أَنَّ ٱلۡفُلۡكَ تَجۡرِي فِي ٱلۡبَحۡرِ بِنِعۡمَتِ ٱللَّهِ لِيُرِيَكُم مِّنۡ ءَايَٰتِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ","3526":"وَجَعَلۡنَا مِنۡهُمۡ أَئِمَّةٗ يَهۡدُونَ بِأَمۡرِنَا لَمَّا صَبَرُواْۖ وَكَانُواْ بِـَٔايَٰتِنَا يُوقِنُونَ","3567":"إِنَّ ٱلۡمُسۡلِمِينَ وَٱلۡمُسۡلِمَٰتِ وَٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ وَٱلۡقَٰنِتِينَ وَٱلۡقَٰنِتَٰتِ وَٱلصَّٰدِقِينَ وَٱلصَّٰدِقَٰتِ وَٱلصَّٰبِرِينَ وَٱلصَّٰبِرَٰتِ وَٱلۡخَٰشِعِينَ وَٱلۡخَٰشِعَٰتِ وَٱلۡمُتَصَدِّقِينَ وَٱلۡمُتَصَدِّقَٰتِ وَٱلصَّٰٓئِمِينَ وَٱلصَّٰٓئِمَٰتِ وَٱلۡحَٰفِظِينَ فُرُوجَهُمۡ وَٱلۡحَٰفِظَٰتِ وَٱلذَّٰكِرِينَ ٱللَّهَ كَثِيرٗا وَٱلذَّٰكِرَٰتِ أَعَدَّ ٱللَّهُ لَهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمٗا","3624":"فَقَالُواْ رَبَّنَا بَٰعِدۡ بَيۡنَ أَسۡفَارِنَا وَظَلَمُوٓاْ أَنفُسَهُمۡ فَجَعَلۡنَٰهُمۡ أَحَادِيثَ وَمَزَّقۡنَٰهُمۡ كُلَّ مُمَزَّقٍۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٖ","3887":"رَبِّ هَبۡ لِي مِنَ ٱلصَّٰلِحِينَ","3888":"فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ","3889":"فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ","4010":"وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ","4011":"ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ","4012":"وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ","4013":"وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ","4067":"قُلۡ يَٰعِبَادِ ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ رَبَّكُمۡۚ لِلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۗ وَأَرۡضُ ٱللَّهِ وَٰسِعَةٌۗ إِنَّمَا يُوَفَّى ٱلصَّٰبِرُونَ أَجۡرَهُم بِغَيۡرِ حِسَابٖ","4187":"فَٱصۡبِرۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ بِٱلۡعَشِيِّ وَٱلۡإِبۡكَٰرِ","4251":"وَلَا تَسۡتَوِي ٱلۡحَسَنَةُ وَلَا ٱلسَّيِّئَةُۚ ٱدۡفَعۡ بِٱلَّتِي هِيَ أَحۡسَنُ فَإِذَا ٱلَّذِي بَيۡنَكَ وَبَيۡنَهُۥ عَدَٰوَةٞ كَأَنَّهُۥ وَلِيٌّ حَمِيمٞ","4252":"وَمَا يُلَقَّىٰهَآ إِلَّا ٱلَّذِينَ صَبَرُواْ وَمَا يُلَقَّىٰهَآ إِلَّا ذُو حَظٍّ عَظِيمٖ","4304":"إِن يَشَأۡ يُسۡكِنِ ٱلرِّيحَ فَيَظۡلَلۡنَ رَوَاكِدَ عَلَىٰ ظَهۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّكُلِّ صَبَّارٖ شَكُورٍ","4311":"وَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ فَمَنۡ عَفَا وَأَصۡلَحَ فَأَجۡرُهُۥ عَلَى ٱللَّهِۚ إِنَّهُۥ لَا يُحِبُّ ٱلظَّٰلِمِينَ","4312":"وَلَمَنِ ٱنتَصَرَ بَعۡدَ ظُلۡمِهِۦ فَأُوْلَٰٓئِكَ مَا عَلَيۡهِم مِّن سَبِيلٍ","4313":"إِنَّمَا ٱلسَّبِيلُ عَلَى ٱلَّذِينَ يَظۡلِمُونَ ٱلنَّاسَ وَيَبۡغُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّۚ أُوْلَٰٓئِكَ لَهُمۡ عَذَابٌ أَلِيمٞ","4314":"وَلَمَن صَبَرَ وَغَفَرَ إِنَّ ذَٰلِكَ لَمِنۡ عَزۡمِ ٱلۡأُمُورِ","4544":"فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۭۚ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ","4782":"وَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ فَإِنَّكَ بِأَعۡيُنِنَاۖ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ حِينَ تَقُومُ","5096":"مَآ أَصَابَ مِن مُّصِيبَةٖ فِي ٱلۡأَرۡضِ وَلَا فِيٓ أَنفُسِكُمۡ إِلَّا فِي كِتَٰبٖ مِّن قَبۡلِ أَن نَّبۡرَأَهَآۚ إِنَّ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٞ","5097":"لِّكَيۡلَا تَأۡسَوۡاْ عَلَىٰ مَا فَاتَكُمۡ وَلَا تَفۡرَحُواْ بِمَآ ءَاتَىٰكُمۡۗ وَٱللَّهُ لَا يُحِبُّ كُلَّ مُخۡتَالٖ فَخُورٍ","5318":"فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تَكُن كَصَاحِبِ ٱلۡحُوتِ إِذۡ نَادَىٰ وَهُوَ مَكۡظُومٞ","5319":"لَّوۡلَآ أَن تَدَٰرَكَهُۥ نِعۡمَةٞ مِّن رَّبِّهِۦ لَنُبِذَ بِٱلۡعَرَآءِ وَهُوَ مَذۡمُومٞ","5320":"فَٱجۡتَبَٰهُ رَبُّهُۥ فَجَعَلَهُۥ مِنَ ٱلصَّٰلِحِينَ","5379":"فَٱصۡبِرۡ صَبۡرٗا جَمِيلًا","5475":"يَٰٓأَيُّهَا ٱلۡمُزَّمِّلُ","5476":"قُمِ ٱلَّيۡلَ إِلَّا قَلِيلٗا","5477":"نِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا","5478":"أَوۡ زِدۡ عَلَيۡهِ وَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا","5479":"إِنَّا سَنُلۡقِي عَلَيۡكَ قَوۡلٗا ثَقِيلًا","5480":"إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا","5481":"إِنَّ لَكَ فِي ٱلنَّهَارِ سَبۡحٗا طَوِيلٗا","5482":"وَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلٗا","5483":"رَّبُّ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ لَآ إِلَٰهَ إِلَّا هُوَ فَٱتَّخِذۡهُ وَكِيلٗا","5484":"وَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱهۡجُرۡهُمۡ هَجۡرٗا جَمِيلٗا","5602":"وَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا","5614":"فَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا","5615":"وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا","5616":"وَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا","6039":"ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ","6176":"وَٱلۡعَصۡرِ","6177":"إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ","6178":"إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ"},"nay":119,"nq":67};
